window.STEPS=Object.assign(window.STEPS||{},{"tb-비상공수2-p052-1":{"길":"거리 공식을 제곱해 a 에 대한 방정식을 세우고 근의 합을 구한다","단계":[{"제목":"거리 공식으로 식 세우기","고비":true,"힌트":"$\\overline{\\mathrm{AB}}=2\\sqrt{13}$ 의 양변을 제곱하면 $(a+1)^{2}$ 은 얼마일까?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{(-4-2)^{2}+(a+1)^{2}}=2\\sqrt{13}$","$36+(a+1)^{2}=52$","$(a+1)^{2}=16$"],"설명":"두 점 사이의 거리는 $x$ 좌표의 차와 $y$ 좌표의 차의 제곱을 더해 근호를 씌운 값이다. 양변을 제곱하면 근호가 없어진다.","확인":"16","스킬":"S3"},{"제목":"a 의 값들의 합","힌트":"$(a+1)^{2}=16$ 을 만족하는 $a$ 는 모두 몇 개이고 합은?","식":["$a+1=\\pm4$ 에서 $a=3$ 또는 $a=-5$","$3+(-5)=-2$"],"설명":"제곱해서 $16$ 이 되는 수는 $4$ 와 $-4$ 두 개이다. 실수 $a$ 가 두 개이므로 둘을 모두 더한다.","확인":"-2","스킬":"A2"}]},"tb-비상공수2-p052-2":{"길":"AB 와 AC 의 제곱을 같다고 놓아 근호 없이 a 를 구한다","단계":[{"제목":"AB², AC² 를 a 로 나타내기","고비":true,"힌트":"$\\overline{\\mathrm{AB}}^{2}$ 과 $\\overline{\\mathrm{AC}}^{2}$ 을 좌표의 차로 쓰면?","식":["$\\overline{\\mathrm{AB}}^{2}=a^{2}+(-2-2)^{2}=a^{2}+16$","$\\overline{\\mathrm{AC}}^{2}=(3-a)^{2}+(-1+2)^{2}=a^{2}-6a+10$"],"설명":"거리를 구하지 않고 제곱한 채로 두면 근호가 생기지 않는다. $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}$ 이면 제곱도 같다.","확인":null,"스킬":"S3"},{"제목":"방정식을 풀어 a 구하기","힌트":"$a^{2}+16=a^{2}-6a+10$ 에서 $a^{2}$ 이 사라지면 남는 식은?","식":["$a^{2}+16=a^{2}-6a+10$","$6a=-6$","$a=-1$"],"설명":"양변의 $a^{2}$ 이 서로 소거되어 일차방정식이 된다.","확인":"-1","스킬":"S3"}]},"tb-비상공수2-p052-3":{"길":"내분점과 중점의 좌표를 각각 구해 더한다","단계":[{"제목":"내분점 P 의 좌표 α","고비":true,"힌트":"$1:2$ 로 내분할 때 $\\mathrm{B}$ 와 $\\mathrm{A}$ 에 곱하는 수는 각각?","식":["$\\alpha=\\frac{1\\times9+2\\times(-3)}{1+2}$","$\\alpha=\\frac{3}{3}=1$"],"설명":"$m:n$ 으로 내분하는 점의 좌표는 $\\frac{mx_{2}+nx_{1}}{m+n}$ 이다. 앞의 비 $1$ 이 $\\mathrm{B}$ 의 좌표에, 뒤의 비 $2$ 가 $\\mathrm{A}$ 의 좌표에 곱해진다.","확인":"1","스킬":"A8"},{"제목":"중점 β 와 α+β","힌트":"중점의 좌표는 두 좌표의 평균이다. $\\beta$ 를 구해 $\\alpha$ 와 더하면?","식":["$\\beta=\\frac{-3+9}{2}=3$","$\\alpha+\\beta=1+3=4$"],"설명":"중점은 $1:1$ 로 내분하는 점이므로 두 좌표의 평균이다.","확인":"4","스킬":"A8"}]},"tb-비상공수2-p052-4":{"길":"x좌표와 y좌표를 따로 내분점 공식에 넣어 b 와 a 를 구한다","단계":[{"제목":"x좌표로 b 구하기","고비":true,"힌트":"$2:3$ 으로 내분할 때 $\\mathrm{B}$ 의 $x$ 좌표와 $\\mathrm{A}$ 의 $x$ 좌표에 곱하는 수는 각각?","식":["$b=\\frac{2\\times5+3\\times(-5)}{2+3}$","$b=\\frac{-5}{5}=-1$"],"설명":"내분점의 $x$ 좌표는 $\\frac{mx_{2}+nx_{1}}{m+n}$ 이다. 앞의 비 $2$ 가 $\\mathrm{B}$ 쪽에, 뒤의 비 $3$ 이 $\\mathrm{A}$ 쪽에 곱해진다.","확인":"-1","스킬":"A8"},{"제목":"y좌표로 a 구하기","힌트":"$\\mathrm{P}$ 의 $y$ 좌표가 $1$ 이라는 조건을 같은 공식에 넣으면?","식":["$\\frac{2\\times(-2)+3a}{5}=1$","$3a-4=5$","$a=3$"],"설명":"$y$ 좌표도 같은 비로 내분하므로 $\\frac{2y_{2}+3y_{1}}{5}=1$ 이다. 양변에 $5$ 를 곱해 푼다.","확인":"3","스킬":"A8"}]},"tb-비상공수2-p052-5":{"길":"평행사변형은 두 대각선의 중점이 같다는 조건으로 a, b 를 구한다","단계":[{"제목":"두 대각선의 중점이 같다는 식","고비":true,"힌트":"평행사변형 $\\mathrm{ABCD}$ 에서 대각선 $\\overline{\\mathrm{AC}}$ 와 $\\overline{\\mathrm{BD}}$ 의 중점은 어떤 관계일까?","식":["$\\overline{\\mathrm{AC}}$ 의 중점 $\\left(\\frac{a+2}{2},\\ \\frac{-1-5}{2}\\right)$","$\\overline{\\mathrm{BD}}$ 의 중점 $\\left(\\frac{3-4}{2},\\ \\frac{2+b}{2}\\right)$","두 중점이 같으므로 $x$, $y$ 좌표가 각각 같다"],"설명":"평행사변형의 두 대각선은 서로 다른 것을 이등분하므로 중점이 일치한다. 대각선은 $\\overline{\\mathrm{AC}}$, $\\overline{\\mathrm{BD}}$ 이다.","확인":null,"스킬":"S4"},{"제목":"x좌표로 a 구하기","힌트":"$\\frac{a+2}{2}=\\frac{3-4}{2}$ 에서 $a$ 는?","식":["$a+2=-1$","$a=-3$"],"설명":"분모가 같으므로 분자끼리 같다.","확인":"-3","스킬":"A3"},{"제목":"y좌표로 b 구하기","힌트":"$\\frac{-1-5}{2}=\\frac{2+b}{2}$ 에서 $b$ 는?","식":["$-6=2+b$","$b=-8$"],"설명":"분모가 같으므로 분자끼리 같다.","확인":"-8","스킬":"A3"}]},"tb-비상공수2-p052-6":{"길":"세 내분점의 좌표 합이 세 꼭짓점의 좌표 합과 같음을 이용한다","단계":[{"제목":"내분점의 좌표 합과 꼭짓점의 좌표 합","고비":true,"힌트":"$\\mathrm{D}$, $\\mathrm{E}$, $\\mathrm{F}$ 의 $x$ 좌표를 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$ 의 $x$ 좌표로 쓰고 더하면?","식":["$x_{\\mathrm{D}}=\\frac{x_{\\mathrm{A}}+2x_{\\mathrm{B}}}{3},\\ x_{\\mathrm{E}}=\\frac{x_{\\mathrm{B}}+2x_{\\mathrm{C}}}{3},\\ x_{\\mathrm{F}}=\\frac{x_{\\mathrm{C}}+2x_{\\mathrm{A}}}{3}$","$x_{\\mathrm{D}}+x_{\\mathrm{E}}+x_{\\mathrm{F}}=x_{\\mathrm{A}}+x_{\\mathrm{B}}+x_{\\mathrm{C}}$"],"설명":"$2:1$ 로 내분하면 앞의 점에 $1$, 뒤의 점에 $2$ 가 곱해진다. 세 식을 더하면 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$ 의 좌표가 각각 $3$ 번씩 나와 $3$ 으로 나누어 떨어진다. $y$ 좌표도 같은 결과이다.","확인":null,"스킬":"S7"},{"제목":"무게중심 G 의 y 좌표","힌트":"$\\mathrm{D}$, $\\mathrm{E}$, $\\mathrm{F}$ 의 $y$ 좌표를 더해 $3$ 으로 나누면?","식":["$y_{\\mathrm{G}}=\\frac{y_{\\mathrm{A}}+y_{\\mathrm{B}}+y_{\\mathrm{C}}}{3}=\\frac{2+3+(-2)}{3}$","$y_{\\mathrm{G}}=1$"],"설명":"합이 같으므로 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$ 를 구하지 않고 $\\mathrm{D}$, $\\mathrm{E}$, $\\mathrm{F}$ 의 $y$ 좌표로 계산한다.","확인":"1","스킬":"S7"},{"제목":"무게중심 G 의 x 좌표와 좌표 완성","힌트":"$x$ 좌표도 같은 방법으로 구하면?","식":["$x_{\\mathrm{G}}=\\frac{-1+(-5)+3}{3}=-1$","$\\mathrm{G}(-1,\\ 1)$"],"설명":"$x$ 좌표도 $\\mathrm{D}$, $\\mathrm{E}$, $\\mathrm{F}$ 의 $x$ 좌표 합을 $3$ 으로 나눈다.","확인":null,"스킬":"S7"}]},"tb-비상공수2-p053-1":{"길":"중점을 먼저 구하고 그 점과 주어진 기울기로 직선을 세운다","단계":[{"제목":"선분의 중점 구하기","고비":true,"힌트":"두 점의 $x$ 좌표끼리, $y$ 좌표끼리 평균을 내면?","식":["$\\left(\\frac{-3+(-5)}{2},\\ \\frac{-2+2}{2}\\right)$","$=(-4,\\ 0)$"],"설명":"중점의 좌표는 두 점의 $x$ 좌표의 평균, $y$ 좌표의 평균이다.","확인":"-4","스킬":"G9"},{"제목":"점과 기울기로 직선의 방정식 세우기","힌트":"점 $(-4,\\ 0)$ 을 지나고 기울기가 $-2$ 인 직선의 식은?","식":["$y-0=-2(x+4)$","$y=-2x-8$"],"설명":"점 $(x_{1},\\ y_{1})$ 을 지나고 기울기가 $m$ 인 직선은 $y-y_{1}=m(x-x_{1})$ 이다.","확인":null,"스킬":"G9"}]},"tb-비상공수2-p053-2":{"길":"연립방정식으로 교점을 구한 뒤 두 점을 지나는 직선을 세운다","단계":[{"제목":"두 직선의 교점 구하기","고비":true,"힌트":"두 식을 변끼리 더하면 $y$ 가 사라지는데 $x$ 는?","식":["$(2x-y-7)+(3x+y-8)=0$","$5x=15,\\ x=3$","$y=2\\times3-7=-1$"],"설명":"교점은 두 직선의 방정식을 동시에 만족하는 점이므로 연립방정식의 해이다.","확인":"3","스킬":"A10"},{"제목":"두 점을 지나는 직선의 기울기","힌트":"교점 $(3,\\ -1)$ 과 $(2,\\ 5)$ 의 $y$ 좌표의 차를 $x$ 좌표의 차로 나누면?","식":["$\\frac{5-(-1)}{2-3}=-6$"],"설명":"기울기는 $\\frac{y\\text{ 좌표의 변화}}{x\\text{ 좌표의 변화}}$ 이다.","확인":"-6","스킬":"G9"},{"제목":"직선의 방정식 세우기","힌트":"점 $(3,\\ -1)$ 과 기울기 $-6$ 으로 직선의 식을 쓰면?","식":["$y+1=-6(x-3)$","$y=-6x+17$"],"설명":"한 점과 기울기를 알면 $y-y_{1}=m(x-x_{1})$ 으로 쓴다.","확인":null,"스킬":"G9"}]},"tb-비상공수2-p053-3-1":{"길":"두 직선의 기울기를 구해 평행 조건으로 k 를 정한다","단계":[{"제목":"두 직선의 기울기 구하기","고비":true,"힌트":"$x+ky=2$ 를 $y=(\\ )x+(\\ )$ 꼴로 고치면 기울기는?","식":["$x+ky=2$ 에서 $y=-\\frac{1}{k}x+\\frac{2}{k}$ (기울기 $-\\frac{1}{k}$)","$2x-y=0$ 에서 $y=2x$ (기울기 $2$)"],"설명":"$y$ 에 대해 풀면 $x$ 의 계수가 기울기이다. $k=0$ 이면 $y$ 에 대해 풀 수 없으므로 $k\\ne0$ 이다.","확인":null,"스킬":"G9"},{"제목":"평행 조건으로 k 구하기","힌트":"두 기울기가 같다는 식을 풀면?","식":["$-\\frac{1}{k}=2$","$k=-\\frac{1}{2}$","$y$ 절편 $\\frac{2}{k}=-4\\ne0$ 이므로 겹치지 않는다"],"설명":"평행하려면 기울기가 같고 $y$ 절편이 달라야 한다. $k=-\\frac{1}{2}$ 일 때 $y$ 절편이 $-4$ 와 $0$ 으로 다르다.","확인":"-1/2","스킬":"G9"}]},"tb-비상공수2-p053-3-2":{"길":"두 직선의 기울기를 구해 기울기의 곱이 -1 이 되게 k 를 정한다","단계":[{"제목":"두 직선의 기울기 구하기","힌트":"$x+ky=2$ 와 $2x-y=0$ 을 $y=(\\ )x+(\\ )$ 꼴로 고치면 기울기는?","식":["$x+ky=2$ 에서 기울기 $-\\frac{1}{k}$","$2x-y=0$ 에서 기울기 $2$"],"설명":"$y$ 에 대해 풀면 $x$ 의 계수가 기울기이다. $k\\ne0$ 이다.","확인":null,"스킬":"G9"},{"제목":"수직 조건으로 k 구하기","고비":true,"힌트":"두 기울기의 곱이 얼마가 되어야 수직일까?","식":["$-\\frac{1}{k}\\times2=-1$","$\\frac{2}{k}=1$","$k=2$"],"설명":"두 직선이 수직이면 기울기의 곱이 $-1$ 이다.","확인":"2","스킬":"G9"}]},"tb-비상공수2-p053-4":{"길":"수직 조건으로 b 를 a 로 나타내고 평행 조건에 넣어 a 를 구한다","단계":[{"제목":"수직 조건으로 b 를 a 로 나타내기","힌트":"$ax+y-1=0$ 의 기울기 $-a$ 와 $3x-by+1=0$ 의 기울기를 곱해 $-1$ 로 놓으면?","식":["기울기: $-a$ 와 $\\frac{3}{b}$","$(-a)\\times\\frac{3}{b}=-1$","$b=3a$"],"설명":"$3x-by+1=0$ 을 $y$ 에 대해 풀면 $y=\\frac{3}{b}x+\\frac{1}{b}$ 이다. 수직이므로 기울기의 곱이 $-1$ 이다.","확인":null,"스킬":"G9"},{"제목":"평행 조건으로 a 의 방정식 세우기","고비":true,"힌트":"$x+(b-2)y+5=0$ 의 기울기를 $a$ 로 나타내고 $-a$ 와 같게 놓으면?","식":["기울기 $-\\frac{1}{b-2}$","$-a=-\\frac{1}{b-2}$ 에서 $a(b-2)=1$","$b=3a$ 를 넣으면 $a(3a-2)=1,\\ 3a^{2}-2a-1=0$"],"설명":"평행하면 기울기가 같다. $b-2\\ne0$ 이어야 기울기를 구할 수 있다.","확인":null,"스킬":"A10"},{"제목":"a 의 값 구하기","힌트":"$3a^{2}-2a-1=0$ 을 인수분해하면?","식":["$(3a+1)(a-1)=0$","$a=1$ 또는 $a=-\\frac{1}{3}$"],"설명":"$a=1$ 이면 $b=3$, $a=-\\frac{1}{3}$ 이면 $b=-1$ 이고 두 경우 모두 평행한 직선이 겹치지 않는다.","확인":null,"스킬":"A10"}]},"tb-비상공수2-p053-5":{"길":"삼각형이 안 되는 경우를 한 점에서 만날 때와 평행한 직선이 있을 때로 나눈다","단계":[{"제목":"삼각형이 안 되는 경우 나누기","힌트":"세 직선이 삼각형을 이루지 못하는 경우는 어떤 두 가지일까?","식":["① 세 직선이 한 점에서 만난다","② 세 직선 중 평행한 두 직선이 있다"],"설명":"세 직선이 서로 다른 세 점에서 만나야 삼각형이 만들어진다. 한 점에서 모두 만나거나 두 직선이 평행하면 교점이 세 개가 되지 않는다.","확인":null,"스킬":"G9"},{"제목":"한 점에서 만나는 경우","고비":true,"힌트":"$y=-x$ 와 $y=2x-3$ 의 교점이 $y=mx+3$ 위에 있으려면?","식":["$-x=2x-3$ 에서 $x=1,\\ y=-1$","$-1=m\\times1+3$","$m=-4$"],"설명":"고정된 두 직선의 교점 $(1,\\ -1)$ 을 먼저 구하고 $y=mx+3$ 이 이 점을 지나게 한다.","확인":"-4","스킬":"G9"},{"제목":"평행한 직선이 있는 경우","힌트":"$y=mx+3$ 의 기울기가 다른 두 직선의 기울기와 같아지는 $m$ 은?","식":["$y=-x$ 와 평행: $m=-1$","$y=2x-3$ 과 평행: $m=2$","$m=-4$ 또는 $m=-1$ 또는 $m=2$"],"설명":"$y=-x$ 와 $y=2x-3$ 은 기울기가 달라 평행하지 않으므로 $y=mx+3$ 이 둘 중 하나와 평행한 경우만 따진다. 두 경우 모두 $y$ 절편이 달라 겹치지 않는다.","확인":null,"스킬":"G9"}]},"tb-비상공수2-p053-6":{"길":"수직이등분선은 중점을 지나고 기울기가 수직인 직선이다","단계":[{"제목":"수직이등분선의 기울기","고비":true,"힌트":"직선 $\\mathrm{AB}$ 의 기울기를 구하고 곱이 $-1$ 이 되는 수를 찾으면?","식":["직선 $\\mathrm{AB}$ 의 기울기 $\\frac{6-1}{-2-2}=-\\frac{5}{4}$","수직이등분선의 기울기 $\\frac{4}{5}$"],"설명":"수직이등분선은 $\\mathrm{AB}$ 에 수직이므로 기울기의 곱이 $-1$ 이다.","확인":"4/5","스킬":"G9"},{"제목":"선분 AB 의 중점","힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 의 $y$ 좌표의 평균은?","식":["$\\left(\\frac{2+(-2)}{2},\\ \\frac{1+6}{2}\\right)=\\left(0,\\ \\frac{7}{2}\\right)$"],"설명":"수직이등분선은 선분의 중점을 지난다.","확인":"7/2","스킬":"G9"},{"제목":"직선의 방정식 세우기","힌트":"점 $\\left(0,\\ \\frac{7}{2}\\right)$ 과 기울기 $\\frac{4}{5}$ 로 식을 쓰면?","식":["$y-\\frac{7}{2}=\\frac{4}{5}(x-0)$","$y=\\frac{4}{5}x+\\frac{7}{2}$"],"설명":"지나는 점의 $x$ 좌표가 $0$ 이므로 $\\frac{7}{2}$ 이 $y$ 절편이다.","확인":null,"스킬":"G9"}]},"tb-비상공수2-p054-1":{"길":"점과 직선 사이의 거리 공식으로 절댓값 방정식을 세운다","단계":[{"제목":"거리 공식으로 식 세우기","고비":true,"힌트":"점 $(1,\\ -2)$ 를 $2x-y+k$ 에 넣고 분모에 $\\sqrt{a^{2}+b^{2}}$ 을 쓰면?","식":["$\\frac{|2\\times1-(-2)+k|}{\\sqrt{2^{2}+(-1)^{2}}}=\\sqrt{5}$","$\\frac{|4+k|}{\\sqrt{5}}=\\sqrt{5}$","$|4+k|=5$"],"설명":"점 $(x_{1},\\ y_{1})$ 과 직선 $ax+by+c=0$ 사이의 거리는 $\\frac{|ax_{1}+by_{1}+c|}{\\sqrt{a^{2}+b^{2}}}$ 이다. 양변에 $\\sqrt{5}$ 를 곱한다.","확인":"5","스킬":"C2"},{"제목":"절댓값을 벗겨 k 구하기","힌트":"$|4+k|=5$ 가 되려면 $4+k$ 는 어떤 수여야 할까?","식":["$4+k=5$ 또는 $4+k=-5$","$k=1$ 또는 $k=-9$"],"설명":"절댓값이 $5$ 인 수는 $5$ 와 $-5$ 두 개이다.","확인":null,"스킬":"C2"}]},"tb-비상공수2-p054-2":{"길":"두 거리의 식을 세워 분모가 같음을 이용해 절댓값을 제곱으로 푼다","단계":[{"제목":"두 직선까지의 거리 식 쓰기","힌트":"점 $(0,\\ a)$ 에서 각 직선까지의 거리 공식을 쓰면?","식":["$d_{1}=\\frac{|0+2a-4|}{\\sqrt{1^{2}+2^{2}}}=\\frac{|2a-4|}{\\sqrt{5}}$","$d_{2}=\\frac{|0-a-1|}{\\sqrt{2^{2}+(-1)^{2}}}=\\frac{|-a-1|}{\\sqrt{5}}$"],"설명":"점의 좌표 $(0,\\ a)$ 를 직선의 식에 대입한다. 두 거리의 분모가 모두 $\\sqrt{5}$ 이다.","확인":null,"스킬":"C2"},{"제목":"절댓값 등식을 제곱해 정리","고비":true,"힌트":"분모가 같으므로 $|2a-4|=|a+1|$ 이다. 양변을 제곱하면?","식":["$(2a-4)^{2}=(a+1)^{2}$","$4a^{2}-16a+16=a^{2}+2a+1$","$a^{2}-6a+5=0$"],"설명":"$|A|=|B|$ 이면 $A^{2}=B^{2}$ 이므로 경우를 나누지 않고 제곱으로 풀 수 있다. 이항해 정리한 뒤 양변을 $3$ 으로 나눈다.","확인":null,"스킬":"C2"},{"제목":"a 의 값 구하기","힌트":"$a^{2}-6a+5=0$ 을 인수분해하면?","식":["$(a-1)(a-5)=0$","$a=1$ 또는 $a=5$"],"설명":"합이 $6$ 이고 곱이 $5$ 인 두 수는 $1$ 과 $5$ 이다.","확인":null,"스킬":"C2"}]},"tb-비상공수2-p054-3":{"길":"한 직선 위의 점을 골라 다른 직선까지의 거리로 평행선 사이의 거리를 잰다","단계":[{"제목":"첫 직선 위의 점 고르기","고비":true,"힌트":"$2x-y-1=0$ 위의 점 중 $x=0$ 인 점은?","식":["$x=0$ 이면 $-y-1=0$ 에서 $y=-1$","점 $(0,\\ -1)$"],"설명":"평행한 두 직선 사이의 거리는 한 직선 위의 아무 점에서 다른 직선까지 잰 거리와 같다. 계산이 쉬운 점 $(0,\\ -1)$ 을 고른다.","확인":null,"스킬":"C2"},{"제목":"점과 직선 사이의 거리 식","힌트":"점 $(0,\\ -1)$ 에서 $2x-y+a=0$ 까지의 거리를 $2\\sqrt{5}$ 와 같게 놓으면?","식":["$\\frac{|0+1+a|}{\\sqrt{2^{2}+(-1)^{2}}}=\\frac{|1+a|}{\\sqrt{5}}=2\\sqrt{5}$","$|1+a|=10$"],"설명":"양변에 $\\sqrt{5}$ 를 곱하면 $2\\sqrt{5}\\times\\sqrt{5}=10$ 이다.","확인":"10","스킬":"C2"},{"제목":"a 의 값 구하기","힌트":"$|1+a|=10$ 이 되려면 $1+a$ 는 어떤 수여야 할까?","식":["$1+a=10$ 또는 $1+a=-10$","$a=9$ 또는 $a=-11$"],"설명":"절댓값이 $10$ 인 수는 $10$ 과 $-10$ 두 개이다.","확인":null,"스킬":"C2"}]},"tb-비상공수2-p054-4":{"길":"평행한 직선은 상수항만 미지수로 두고 거리 공식으로 정한다","단계":[{"제목":"구하는 직선의 꼴 놓기","고비":true,"힌트":"$x-3y-2=0$ 에 평행한 직선에서 그대로 두는 것과 바꾸는 것은?","식":["평행하면 $x$, $y$ 의 계수는 그대로","$x-3y+c=0$"],"설명":"평행한 직선은 기울기가 같으므로 $x$, $y$ 의 계수의 비가 같다. 계수는 그대로 두고 상수항만 $c$ 로 놓는다.","확인":null,"스킬":"G9"},{"제목":"거리 공식으로 식 세우기","힌트":"점 $(-1,\\ 3)$ 에서 $x-3y+c=0$ 까지의 거리를 $\\sqrt{10}$ 과 같게 놓으면?","식":["$\\frac{|1\\times(-1)-3\\times3+c|}{\\sqrt{1^{2}+(-3)^{2}}}=\\sqrt{10}$","$\\frac{|c-10|}{\\sqrt{10}}=\\sqrt{10}$","$|c-10|=10$"],"설명":"분자는 $-1-9+c=c-10$ 이고 분모는 $\\sqrt{10}$ 이다. 양변에 $\\sqrt{10}$ 을 곱한다.","확인":"10","스킬":"C2"},{"제목":"c 의 값과 직선의 방정식","힌트":"$|c-10|=10$ 에서 $c-10$ 은 어떤 수일까?","식":["$c-10=10$ 또는 $c-10=-10$","$c=20$ 또는 $c=0$","$x-3y+20=0$ 또는 $x-3y=0$"],"설명":"절댓값이 $10$ 인 수는 $10$ 과 $-10$ 이므로 직선이 두 개이다.","확인":null,"스킬":"C2"}]},"tb-비상공수2-p054-5":{"길":"수직인 직선은 계수를 바꾸고 부호를 뒤집어 놓고 거리 공식으로 정한다","단계":[{"제목":"구하는 직선의 꼴 놓기","고비":true,"힌트":"$3x+4y-6=0$ 의 기울기와 곱이 $-1$ 이 되는 기울기를 가진 꼴은?","식":["$3x+4y-6=0$ 의 기울기 $-\\frac{3}{4}$","수직인 직선의 기울기 $\\frac{4}{3}$","$4x-3y+c=0$"],"설명":"기울기의 곱이 $-1$ 이어야 수직이다. $4x-3y+c=0$ 은 $y=\\frac{4}{3}x+\\frac{c}{3}$ 로 기울기가 $\\frac{4}{3}$ 이다.","확인":null,"스킬":"G9"},{"제목":"거리 공식으로 식 세우기","힌트":"점 $(2,\\ 1)$ 에서 $4x-3y+c=0$ 까지의 거리를 $2$ 와 같게 놓으면?","식":["$\\frac{|4\\times2-3\\times1+c|}{\\sqrt{4^{2}+(-3)^{2}}}=2$","$\\frac{|5+c|}{5}=2$","$|5+c|=10$"],"설명":"분모는 $\\sqrt{16+9}=5$ 이다. 양변에 $5$ 를 곱한다.","확인":"10","스킬":"C2"},{"제목":"c 의 값과 직선의 방정식","힌트":"$|5+c|=10$ 에서 $5+c$ 는 어떤 수일까?","식":["$5+c=10$ 또는 $5+c=-10$","$c=5$ 또는 $c=-15$","$4x-3y+5=0$ 또는 $4x-3y-15=0$"],"설명":"절댓값이 $10$ 인 수는 $10$ 과 $-10$ 이므로 직선이 두 개이다.","확인":null,"스킬":"C2"}]},"tb-비상공수2-p054-6":{"길":"밑변 AB 의 길이와 O 에서 직선 AB 까지의 거리를 곱해 넓이를 구한다","단계":[{"제목":"밑변 AB 의 길이","힌트":"$\\mathrm{A}(2,\\ 4)$, $\\mathrm{B}(3,\\ 3)$ 사이의 거리는?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{(3-2)^{2}+(3-4)^{2}}=\\sqrt{2}$"],"설명":"$x$ 좌표의 차와 $y$ 좌표의 차가 모두 $1$ 이다.","확인":null,"스킬":"G10"},{"제목":"직선 AB 의 방정식","힌트":"$\\mathrm{A}$, $\\mathrm{B}$ 를 지나는 직선의 기울기와 $y$ 절편은?","식":["기울기 $\\frac{3-4}{3-2}=-1$","$y-4=-(x-2),\\ y=-x+6$","$x+y-6=0$"],"설명":"점 $\\mathrm{A}$ 와 기울기 $-1$ 로 직선을 세우고 $x$, $y$ 를 한쪽으로 모은다. $y$ 절편이 구하려는 값이다.","확인":"6","스킬":"G10"},{"제목":"높이: O 에서 직선 AB 까지의 거리","고비":true,"힌트":"원점과 직선 $x+y-6=0$ 사이의 거리는?","식":["$\\frac{|0+0-6|}{\\sqrt{1^{2}+1^{2}}}=\\frac{6}{\\sqrt{2}}=3\\sqrt{2}$"],"설명":"$\\overline{\\mathrm{AB}}$ 를 밑변으로 보면 높이는 $\\mathrm{O}$ 에서 직선 $\\mathrm{AB}$ 까지의 거리이다.","확인":null,"스킬":"G10"},{"제목":"삼각형 OAB 의 넓이","힌트":"밑변과 높이를 곱해 $\\frac{1}{2}$ 을 곱하면?","식":["$\\frac{1}{2}\\times\\sqrt{2}\\times3\\sqrt{2}=3$"],"설명":"$\\sqrt{2}\\times\\sqrt{2}=2$ 이므로 $\\frac{1}{2}\\times3\\times2=3$ 이다.","확인":"3","스킬":"G10"}]},"tb-비상공수2-p055-1":{"길":"반지름은 중심과 지나는 점 사이의 거리이다","단계":[{"제목":"반지름 구하기","고비":true,"힌트":"중심 $(-3,\\ 2)$ 와 지나는 점 $(1,\\ 2)$ 사이의 거리는?","식":["$r=\\sqrt{(1+3)^{2}+(2-2)^{2}}=4$"],"설명":"원 위의 점과 중심 사이의 거리가 반지름이다. 두 점의 $y$ 좌표가 같아 $x$ 좌표의 차가 거리이다.","확인":"4","스킬":"A6"},{"제목":"원의 방정식 쓰기","힌트":"중심 $(a,\\ b)$, 반지름 $r$ 인 원의 방정식에 대입하면?","식":["$(x+3)^{2}+(y-2)^{2}=16$"],"설명":"중심이 $(-3,\\ 2)$ 이므로 $(x-(-3))^{2}+(y-2)^{2}=r^{2}$ 이고 $r^{2}=16$ 이다.","확인":null,"스킬":"A6"}]},"tb-비상공수2-p055-2":{"길":"두 축에 접하면 중심이 (-r, r) 꼴이라 반지름 하나만 구하면 된다","단계":[{"제목":"중심과 반지름 놓기","고비":true,"힌트":"$x$축, $y$축에 동시에 접하면 중심에서 두 축까지의 거리는? 점 $(-1,\\ 2)$ 는 몇 사분면일까?","식":["점 $(-1,\\ 2)$ 는 제$2$사분면의 점","중심 $(-r,\\ r)$, 반지름 $r\\ (r>0)$","$(x+r)^{2}+(y-r)^{2}=r^{2}$"],"설명":"두 축에 접하면 중심의 $x$ 좌표와 $y$ 좌표의 절댓값이 모두 반지름 $r$ 이다. 원이 지나는 점이 제$2$사분면이므로 원도 제$2$사분면에 있어 중심이 $(-r,\\ r)$ 이다.","확인":null,"스킬":"A6"},{"제목":"점을 대입해 r 구하기","힌트":"$(-1,\\ 2)$ 를 $(x+r)^{2}+(y-r)^{2}=r^{2}$ 에 넣고 정리하면?","식":["$(r-1)^{2}+(2-r)^{2}=r^{2}$","$r^{2}-6r+5=0$","$(r-1)(r-5)=0$"],"설명":"좌변을 전개하면 $2r^{2}-6r+5$ 이고 우변 $r^{2}$ 을 이항한다.","확인":null,"스킬":"A6"},{"제목":"반지름에 따른 원의 방정식","힌트":"$r=1$ 과 $r=5$ 를 각각 대입하면?","식":["$r=1$: $(x+1)^{2}+(y-1)^{2}=1$","$r=5$: $(x+5)^{2}+(y-5)^{2}=25$"],"설명":"두 값 모두 양수이므로 원이 두 개이다.","확인":null,"스킬":"A6"}]},"tb-비상공수2-p055-3":{"길":"지름의 양 끝점이면 중심은 중점이고 반지름은 중점까지의 거리이다","단계":[{"제목":"중심 구하기","고비":true,"힌트":"지름의 양 끝점 $\\mathrm{A}$, $\\mathrm{B}$ 의 중점이 원의 무엇일까?","식":["$\\left(\\frac{2+(-4)}{2},\\ \\frac{5+(-1)}{2}\\right)=(-1,\\ 2)$","$a=-1,\\ b=2$"],"설명":"지름의 중점이 원의 중심이다.","확인":"-1","스킬":"S4"},{"제목":"반지름 구하기","힌트":"중심 $(-1,\\ 2)$ 와 $\\mathrm{A}(2,\\ 5)$ 사이의 거리는?","식":["$r=\\sqrt{(2+1)^{2}+(5-2)^{2}}=\\sqrt{18}=3\\sqrt{2}$"],"설명":"중심과 원 위의 점 사이의 거리가 반지름이다. $r>0$ 이므로 양의 값을 택한다.","확인":null,"스킬":"S4"}]},"tb-비상공수2-p055-4":{"길":"중심을 (a, a) 로 놓고 두 점까지의 거리가 같다고 놓는다","단계":[{"제목":"중심을 (a, a) 로 놓고 식 세우기","고비":true,"힌트":"중심에서 두 점 $(-6,\\ 0)$, $(0,\\ 6)$ 까지의 거리의 제곱을 같다고 놓으면?","식":["중심 $(a,\\ a)$","$(a+6)^{2}+a^{2}=a^{2}+(a-6)^{2}$","$24a=0,\\ a=0$"],"설명":"중심은 직선 $y=x$ 위에 있으므로 $(a,\\ a)$ 로 놓는다. 원 위의 점은 중심까지 거리가 모두 같다. 양변의 $a^{2}$ 이 소거된다.","확인":"0","스킬":"S4"},{"제목":"원의 방정식 쓰기","힌트":"중심이 원점이고 $(0,\\ 6)$ 을 지나면 반지름은?","식":["$r=6$","$x^{2}+y^{2}=36$"],"설명":"중심 $(0,\\ 0)$ 에서 $(0,\\ 6)$ 까지의 거리가 반지름이다.","확인":null,"스킬":"S4"}]},"tb-비상공수2-p055-5":{"길":"일반형에 세 점을 대입하되 원점을 먼저 넣어 C 를 정한다","단계":[{"제목":"원점을 대입해 C 구하기","힌트":"$x^{2}+y^{2}+Ax+By+C=0$ 에 $(0,\\ 0)$ 을 넣으면?","식":["$0+0+0+0+C=0$","$C=0$"],"설명":"원점을 지나므로 $x=0$, $y=0$ 일 때 상수항 $C$ 만 남는다.","확인":"0","스킬":"A10"},{"제목":"나머지 두 점을 대입해 A, B 구하기","고비":true,"힌트":"$(0,\\ 4)$ 와 $(4,\\ 0)$ 을 각각 대입하면 $B$, $A$ 는?","식":["$(0,\\ 4)$: $16+4B=0$ 에서 $B=-4$","$(4,\\ 0)$: $16+4A=0$ 에서 $A=-4$"],"설명":"$(0,\\ 4)$ 에서는 $y^{2}=16$ 과 $By=4B$ 가 남고, $(4,\\ 0)$ 에서는 $x^{2}=16$ 과 $Ax=4A$ 가 남는다.","확인":"-4","스킬":"A10"},{"제목":"원의 방정식 쓰기","힌트":"구한 $A$, $B$, $C$ 를 일반형에 넣으면?","식":["$x^{2}+y^{2}-4x-4y=0$"],"설명":"$C=0$ 이므로 상수항은 없다.","확인":null,"스킬":"A10"}]},"tb-비상공수2-p055-6":{"길":"완전제곱 꼴로 바꿔 우변이 양수가 되는 조건을 쓴다","단계":[{"제목":"완전제곱 꼴로 고치기","고비":true,"힌트":"$x$ 에 대한 항과 $y$ 에 대한 항을 각각 완전제곱식으로 만들면 우변은?","식":["$\\left(x-\\frac{3}{2}\\right)^{2}+(y+1)^{2}=\\frac{9}{4}+1-k$","$\\left(x-\\frac{3}{2}\\right)^{2}+(y+1)^{2}=\\frac{13}{4}-k$"],"설명":"$x^{2}-3x$ 에는 $\\frac{9}{4}$ 를, $y^{2}+2y$ 에는 $1$ 을 더해 완전제곱식을 만들고 같은 값을 우변에도 더한다.","확인":"13/4","스킬":"A6"},{"제목":"원이 될 조건","힌트":"우변은 반지름의 제곱이다. 어떤 부호여야 원일까?","식":["$\\frac{13}{4}-k>0$","$k<\\frac{13}{4}$"],"설명":"우변이 $0$ 이면 한 점, 음수이면 아무 점도 없다. 양수일 때만 반지름이 $\\sqrt{\\frac{13}{4}-k}$ 인 원이 된다.","확인":null,"스킬":"A6"}]},"tb-비상공수2-p056-1":{"길":"직선을 원의 식에 대입한 이차방정식의 판별식 부호로 판단한다","단계":[{"제목":"직선을 원의 식에 대입하기","힌트":"$y=-x+3$ 을 $x^{2}+y^{2}-3y+2=0$ 에 넣고 정리하면?","식":["$x^{2}+(-x+3)^{2}-3(-x+3)+2=0$","$2x^{2}-3x+2=0$"],"설명":"원과 직선의 교점은 두 식을 동시에 만족하는 점이므로 $y$ 를 소거한 $x$ 에 대한 이차방정식의 실근과 같다.","확인":null,"스킬":"G2"},{"제목":"판별식으로 위치 관계 판단","고비":true,"힌트":"$2x^{2}-3x+2=0$ 의 판별식 $D$ 는?","식":["$D=(-3)^{2}-4\\times2\\times2=-7$","$D<0$ 이므로 만나지 않는다"],"설명":"$D>0$ 이면 서로 다른 두 점에서 만나고, $D=0$ 이면 접하고, $D<0$ 이면 만나지 않는다.","확인":"-7","스킬":"G2"}]},"tb-비상공수2-p056-2":{"길":"접하면 중심에서 직선까지의 거리가 반지름과 같다는 점을 쓴다","단계":[{"제목":"접하는 조건 세우기","힌트":"원과 직선이 접할 때 중심에서 직선까지의 거리는 무엇과 같은가?","식":["$d=r$"],"설명":"원과 직선이 접하면 원의 중심에서 직선까지의 거리 $d$가 반지름 $r$과 같다. 이 원의 중심은 원점이다.","확인":null,"스킬":"G2"},{"제목":"원점에서 직선까지의 거리 계산","힌트":"점과 직선 사이의 거리 공식에 원점을 대입하면 어떤 식이 되는가?","식":["$d=\\frac{|3\\cdot0-0-10|}{\\sqrt{3^{2}+(-1)^{2}}}=\\frac{10}{\\sqrt{10}}$","$r=d=\\sqrt{10}$"],"설명":"거리 공식에 원점 $(0,\\ 0)$을 대입한다. 분모를 유리화하면 $\\sqrt{10}$이고, 이 값이 반지름이다.","확인":null,"스킬":"G2","고비":true}]},"tb-비상공수2-p056-3":{"길":"수직 조건으로 기울기를 정한 뒤 원의 접선 공식에 넣는다","단계":[{"제목":"수직인 직선의 기울기","힌트":"수직인 두 직선의 기울기의 곱은 얼마인가?","식":["$\\frac{1}{2}\\cdot m=-1$","$m=-2$"],"설명":"두 직선이 수직이면 기울기의 곱이 $-1$이다. 구하는 접선의 기울기는 $-2$이다.","확인":"-2","스킬":"G9"},{"제목":"기울기가 주어진 접선 공식 대입","힌트":"반지름 $2$인 원에 기울기 $m$으로 접하는 직선은 어떤 꼴인가?","식":["$y=-2x\\pm2\\sqrt{(-2)^{2}+1}$"],"설명":"원 $x^{2}+y^{2}=r^{2}$에 접하고 기울기가 $m$인 직선은 $y=mx\\pm r\\sqrt{m^{2}+1}$이다. 여기서 $r=2$, $m=-2$이다.","확인":null,"스킬":"G2","고비":true},{"제목":"접선의 방정식 정리","힌트":"근호 안을 계산하면 접선은 어떻게 쓰이는가?","식":["$y=-2x\\pm2\\sqrt{5}$"],"설명":"근호 안은 $4+1=5$이다. 부호 $\\pm$ 때문에 접선은 두 개이다.","확인":null,"스킬":"G2"}]},"tb-비상공수2-p056-4":{"길":"원 위의 점에서의 접선을 먼저 구해 기울기를 얻는다","단계":[{"제목":"점 $(4,\\ 3)$에서의 접선 $l$","힌트":"원 $x^{2}+y^{2}=r^{2}$ 위의 점 $(x_{1},\\ y_{1})$에서의 접선은 어떤 식인가?","식":["$l:\\ 4x+3y=25$","$y=-\\frac{4}{3}x+\\frac{25}{3}$"],"설명":"접선의 방정식은 $x_{1}x+y_{1}y=r^{2}$이다. $y$에 대해 정리하면 기울기를 읽을 수 있다.","확인":"-4/3","스킬":"G2"},{"제목":"수직인 직선의 기울기","힌트":"$l$의 기울기에 곱해서 $-1$이 되는 수는 무엇인가?","식":["$-\\frac{4}{3}\\cdot m=-1$","$m=\\frac{3}{4}$"],"설명":"수직인 두 직선은 기울기의 곱이 $-1$이다.","확인":"3/4","스킬":"G9"},{"제목":"접선 공식 대입","힌트":"반지름 $5$인 원에 기울기 $\\frac{3}{4}$로 접하는 직선은 어떤 꼴인가?","식":["$y=\\frac{3}{4}x\\pm5\\sqrt{\\left(\\frac{3}{4}\\right)^{2}+1}$","$\\sqrt{\\frac{9}{16}+1}=\\frac{5}{4}$"],"설명":"기울기가 $m$인 접선은 $y=mx\\pm r\\sqrt{m^{2}+1}$이다. 근호 안은 $\\frac{25}{16}$이므로 $\\frac{5}{4}$가 된다.","확인":null,"스킬":"G2","고비":true},{"제목":"접선의 방정식 정리","힌트":"$5\\cdot\\frac{5}{4}$를 계산하면 상수항은 얼마인가?","식":["$y=\\frac{3}{4}x\\pm\\frac{25}{4}$"],"설명":"$5\\cdot\\frac{5}{4}=\\frac{25}{4}$이므로 접선은 두 개이다.","확인":null,"스킬":"G2"}]},"tb-비상공수2-p056-5":{"길":"교점을 구하고 중심과의 위치로 두 접선의 모양을 읽는다","단계":[{"제목":"원의 중심과 반지름","힌트":"$x$와 $y$를 각각 완전제곱식으로 묶으면 원의 식은 어떻게 되는가?","식":["$(x-1)^{2}+(y-3)^{2}=9$"],"설명":"$x^{2}-2x$와 $y^{2}-6y$를 각각 완전제곱으로 만든다. 중심은 $(1,\\ 3)$, 반지름은 $3$이다.","확인":null,"스킬":"A6"},{"제목":"원과 직선의 교점","힌트":"$y=x-1$을 원의 식에 대입하면 $x$에 대한 방정식은 무엇인가?","식":["$x^{2}-5x+4=0$","$(1,\\ 0),\\ (4,\\ 3)$"],"설명":"$y=x-1$을 대입해 정리하면 $(x-1)(x-4)=0$이다. 각 $x$에 대응하는 $y$는 직선의 식으로 구한다.","확인":null,"스킬":"G1"},{"제목":"두 교점에서의 접선","힌트":"중심 $(1,\\ 3)$에서 각 교점은 어느 방향에 있는가?","식":["$y=0$","$x=4$"],"설명":"$(1,\\ 0)$은 중심의 바로 아래이므로 반지름이 수직이고 접선은 수평이다. $(4,\\ 3)$은 중심의 바로 오른쪽이므로 반지름이 수평이고 접선은 수직이다.","확인":null,"스킬":"S5","고비":true},{"제목":"두 접선의 교점","힌트":"$y=0$과 $x=4$를 동시에 만족하는 점은 어디인가?","식":["$(4,\\ 0)$"],"설명":"두 접선 $y=0$, $x=4$의 교점이 구하는 점이다.","확인":null,"스킬":"G1"}]},"tb-비상공수2-p056-6":{"길":"접점을 미지수로 두고 접선이 주어진 점을 지난다는 조건을 쓴다","단계":[{"제목":"접점을 문자로 둔 접선","힌트":"접점을 $(x_{1},\\ y_{1})$이라 하면 접선의 식은 어떻게 쓰는가?","식":["$x_{1}x+y_{1}y=4$"],"설명":"원 위의 점 $(x_{1},\\ y_{1})$에서의 접선은 $x_{1}x+y_{1}y=4$이다.","확인":null,"스킬":"D7"},{"제목":"지나는 점 조건","힌트":"접선이 $(2,\\ -1)$을 지나면 $x_{1}$, $y_{1}$ 사이에 어떤 관계가 생기는가?","식":["$2x_{1}-y_{1}=4$"],"설명":"접선의 식에 $x=2$, $y=-1$을 대입한다.","확인":null,"스킬":"D7"},{"제목":"접점의 좌표 연립","힌트":"접점은 원 위의 점이기도 하다. 두 식을 연립하면 어떻게 되는가?","식":["$y_{1}=2x_{1}-4$","$5x_{1}^{2}-16x_{1}+12=0$","$(x_{1},\\ y_{1})=(2,\\ 0),\\ \\left(\\frac{6}{5},\\ -\\frac{8}{5}\\right)$"],"설명":"접점이 원 위에 있으므로 $x_{1}^{2}+y_{1}^{2}=4$이다. $y_{1}=2x_{1}-4$를 대입하면 $(x_{1}-2)(5x_{1}-6)=0$이다.","확인":null,"스킬":"A10","고비":true},{"제목":"접선의 방정식","힌트":"두 접점을 접선의 식에 각각 대입하면 어떻게 되는가?","식":["$x=2$","$3x-4y=10$"],"설명":"$(2,\\ 0)$에서는 $2x=4$이고, $\\left(\\frac{6}{5},\\ -\\frac{8}{5}\\right)$에서는 $\\frac{6}{5}x-\\frac{8}{5}y=4$이므로 양변에 $\\frac{5}{2}$를 곱한다.","확인":null,"스킬":"D7"}]},"tb-비상공수2-p057-1":{"길":"어디서 출발해도 옮긴 가로·세로 길이가 같음을 이용한다","단계":[{"제목":"점 B의 좌표 표현","힌트":"$\\mathrm{A}(a,\\ b)$라 하면 평행이동한 점 $\\mathrm{B}$는 어떻게 쓰이는가?","식":["$\\mathrm{B}(a+3,\\ b-2)$"],"설명":"$x$좌표에 $3$을 더하고 $y$좌표에서 $2$를 뺀다.","확인":null,"스킬":"G4"},{"제목":"선분 AB의 길이","힌트":"두 점의 $x$좌표 차와 $y$좌표 차로 거리를 구하면?","식":["$\\overline{\\mathrm{AB}}=\\sqrt{3^{2}+(-2)^{2}}=\\sqrt{13}$"],"설명":"가로 방향 차가 $3$, 세로 방향 차가 $-2$이므로 피타고라스 정리로 거리를 구한다. $a$, $b$는 소거된다.","확인":null,"스킬":"S3","고비":true}]},"tb-비상공수2-p057-2":{"길":"이동량을 먼저 읽고 같은 이동을 다른 점에 적용한다","단계":[{"제목":"평행이동의 이동량","힌트":"점 $(2,\\ 3)$이 점 $(4,\\ 0)$으로 가려면 각 좌표가 얼마나 변하는가?","식":["$(x,\\ y)\\to(x+2,\\ y-3)$"],"설명":"$x$좌표는 $2$만큼, $y$좌표는 $-3$만큼 변한다.","확인":null,"스킬":"G4"},{"제목":"점 $(a,\\ 4)$의 이동","힌트":"같은 이동을 점 $(a,\\ 4)$에 적용하면 어떤 좌표가 되는가?","식":["$(a+2,\\ 4-3)=(a+2,\\ 1)$"],"설명":"$x$좌표에 $2$를 더하고 $y$좌표에서 $3$을 뺀다.","확인":null,"스킬":"G4","고비":true},{"제목":"$a$, $b$의 값","힌트":"이동한 점이 $(5,\\ b)$와 같으려면 각 좌표를 어떻게 비교하는가?","식":["$a+2=5$","$a=3,\\ b=1$"],"설명":"두 점의 $x$좌표끼리, $y$좌표끼리 같다.","확인":null,"스킬":"G4"}]},"tb-비상공수2-p057-3":{"길":"도형의 평행이동은 $x$, $y$ 대신 이동한 만큼 뺀 식을 쓴다","단계":[{"제목":"평행이동한 직선의 방정식","힌트":"$x$ 대신 $x-a$, $y$ 대신 $y-3$을 넣으면 식은 어떻게 되는가?","식":["$y-3=2(x-a)+1$","$y=2x-2a+4$"],"설명":"도형을 $x$축으로 $a$, $y$축으로 $3$만큼 옮기면 $x$ 자리에 $x-a$, $y$ 자리에 $y-3$을 넣는다.","확인":null,"스킬":"G4","고비":true},{"제목":"지나는 점 조건으로 $a$ 구하기","힌트":"점 $(5,\\ -4)$를 식에 대입하면 $a$에 대한 방정식은?","식":["$-4=2\\cdot5-2a+4$","$a=9$"],"설명":"$-4=14-2a$에서 $2a=18$이다.","확인":"9","스킬":"G4"}]},"tb-비상공수2-p057-4":{"길":"원의 중심이 옮겨진 만큼을 읽어 직선에도 똑같이 적용한다","단계":[{"제목":"원을 완전제곱 꼴로 정리","힌트":"$x$와 $y$를 각각 완전제곱식으로 묶으면 두 번째 원의 식은?","식":["$(x-2)^{2}+(y+5)^{2}=29$"],"설명":"$x^{2}-4x$와 $y^{2}+10y$를 각각 완전제곱으로 만들면 중심이 $(2,\\ -5)$이고 반지름은 $\\sqrt{29}$로 같다.","확인":null,"스킬":"A6"},{"제목":"평행이동의 이동량","힌트":"중심이 원점에서 $(2,\\ -5)$로 갔다면 이동량은 얼마인가?","식":["$(x,\\ y)\\to(x+2,\\ y-5)$"],"설명":"원점이 중심인 원이 새 중심으로 옮겨졌으므로 이동량은 새 중심의 좌표와 같다.","확인":null,"스킬":"G4"},{"제목":"직선의 평행이동","힌트":"직선의 $x$ 자리에 $x-2$, $y$ 자리에 $y+5$를 넣으면 식은?","식":["$y+5=-(x-2)+8$","$y=-x+5$"],"설명":"도형의 평행이동은 이동한 만큼 빼서 대입하므로 부호가 반대로 들어간다.","확인":null,"스킬":"G4","고비":true}]},"tb-비상공수2-p057-5":{"길":"원은 중심만 따라가므로 이동 전후의 중심을 비교한다","단계":[{"제목":"처음 원의 중심 구하기","힌트":"$x$와 $y$를 각각 완전제곱식으로 묶으면 원의 식은 어떻게 되는가?","식":["$(x-3)^{2}+(y+4)^{2}=23$"],"설명":"$x^{2}-6x$와 $y^{2}+8y$를 완전제곱으로 만든다. 중심은 $(3,\\ -4)$이고 반지름은 이동 후와 같다.","확인":null,"스킬":"A6"},{"제목":"중심의 이동으로 $a$, $b$ 구하기","힌트":"중심 $(3,\\ -4)$가 $(-2,\\ 1)$로 가려면 각 좌표에 무엇을 더해야 하는가?","식":["$3+a=-2$","$-4+b=1$","$a=-5,\\ b=5$"],"설명":"평행이동은 중심도 같은 만큼 옮기므로 $x$좌표에 $a$, $y$좌표에 $b$를 더한 값이 새 중심이 된다.","확인":null,"스킬":"G4","고비":true}]},"tb-비상공수2-p057-6":{"길":"만난다는 조건을 중심과 직선 사이의 거리 부등식으로 바꾼다","단계":[{"제목":"평행이동한 원의 방정식","힌트":"$x$ 자리에 $x+1$, $y$ 자리에 $y-k$를 넣으면 원의 식은?","식":["$(x+1)^{2}+(y-k)^{2}=2$"],"설명":"중심이 $(-1,\\ k)$이고 반지름이 $\\sqrt{2}$인 원이 된다.","확인":null,"스킬":"G4"},{"제목":"만나는 조건","힌트":"원과 직선이 만나려면 중심에서 직선까지의 거리 $d$는 반지름과 어떤 관계인가?","식":["$d\\le\\sqrt{2}$"],"설명":"접하거나 두 점에서 만나는 경우를 모두 포함하므로 거리가 반지름 이하이다.","확인":null,"스킬":"G2"},{"제목":"거리 부등식 세우기","힌트":"중심 $(-1,\\ k)$에서 직선 $2x+2y-3=0$까지의 거리를 식으로 쓰면?","식":["$\\frac{|2\\cdot(-1)+2k-3|}{\\sqrt{2^{2}+2^{2}}}=\\frac{|2k-5|}{\\sqrt{8}}\\le\\sqrt{2}$","$|2k-5|\\le4$"],"설명":"양변에 $\\sqrt{8}$을 곱하면 $\\sqrt{2}\\cdot\\sqrt{8}=4$이다.","확인":null,"스킬":"G2","고비":true},{"제목":"$k$의 범위","힌트":"$|2k-5|\\le4$를 절댓값 없이 쓰면?","식":["$-4\\le2k-5\\le4$","$\\frac{1}{2}\\le k\\le\\frac{9}{2}$"],"설명":"$|A|\\le4$이면 $-4\\le A\\le4$이다. 각 변에 $5$를 더한 뒤 $2$로 나눈다.","확인":null,"스킬":"G6"}]},"tb-비상공수2-p058-1":{"길":"두 대칭이동한 점의 좌표를 각각 구해 중점 공식에 넣는다","단계":[{"제목":"원점에 대한 대칭이동 점 A","힌트":"원점 대칭이동은 두 좌표의 부호를 어떻게 바꾸는가?","식":["$\\mathrm{A}(-4,\\ 2)$"],"설명":"원점에 대하여 대칭이동하면 $(x,\\ y)\\to(-x,\\ -y)$이다.","확인":null,"스킬":"G4"},{"제목":"직선 $y=x$에 대한 대칭이동 점 B","힌트":"$y=x$ 대칭이동은 두 좌표를 어떻게 바꾸는가?","식":["$\\mathrm{B}(-2,\\ 4)$"],"설명":"직선 $y=x$에 대하여 대칭이동하면 $(x,\\ y)\\to(y,\\ x)$이다.","확인":null,"스킬":"G4","고비":true},{"제목":"선분 AB의 중점","힌트":"두 점의 $x$좌표끼리, $y$좌표끼리 평균을 내면?","식":["$\\mathrm{M}\\left(\\frac{-4+(-2)}{2},\\ \\frac{2+4}{2}\\right)=(-3,\\ 3)$"],"설명":"중점의 좌표는 각 좌표의 평균이다.","확인":null,"스킬":"G4"}]},"tb-비상공수2-p058-2":{"길":"점 P가 옮겨진 순서대로 좌표를 문자로 따라가 방정식을 세운다","단계":[{"제목":"이동 순서대로 좌표 쓰기","힌트":"$y$축 대칭 후 평행이동하면 $\\mathrm{P}(a,\\ b)$는 어떤 좌표가 되는가?","식":["$(a,\\ b)\\to(-a,\\ b)\\to(-a+2,\\ b-3)$"],"설명":"$y$축에 대한 대칭이동은 $x$좌표의 부호만 바꾼다. 이어서 $x$좌표에 $2$를 더하고 $y$좌표에서 $3$을 뺀다.","확인":null,"스킬":"G4","고비":true},{"제목":"좌표 비교","힌트":"최종 점이 $(3,\\ -1)$이므로 각 좌표를 어떻게 맞추는가?","식":["$-a+2=3$","$b-3=-1$"],"설명":"$x$좌표끼리, $y$좌표끼리 같다고 놓는다.","확인":null,"스킬":"C5"},{"제목":"점 P의 좌표","힌트":"두 방정식을 풀면 $a$, $b$는?","식":["$a=-1,\\ b=2$","$\\mathrm{P}(-1,\\ 2)$"],"설명":"각 방정식을 $a$, $b$에 대해 푼다.","확인":null,"스킬":"C5"}]},"tb-비상공수2-p058-3":{"길":"$x$, $y$를 바꾼 식이 원래 식과 같아질 조건을 찾는다","단계":[{"제목":"직선 $y=x$에 대한 대칭이동","힌트":"$x$와 $y$ 자리를 서로 바꾸면 식은 어떻게 되는가?","식":["$ay+2x+3=0$","$2x+ay+3=0$"],"설명":"직선 $y=x$에 대하여 대칭이동하면 $x$와 $y$를 서로 바꾼다.","확인":null,"스킬":"G4"},{"제목":"원래 직선과 일치하는 조건","힌트":"$ax+2y+3=0$과 $2x+ay+3=0$이 같은 직선이려면 계수는 어떤 관계인가?","식":["$a=2$"],"설명":"상수항이 모두 $3$으로 같으므로 $x$의 계수끼리, $y$의 계수끼리 같아야 한다. 즉 $a=2$이다.","확인":"2","스킬":"A3","고비":true}]},"tb-비상공수2-p058-4":{"길":"원의 중심만 대칭이동하고 반지름은 그대로 두어 점을 대입한다","단계":[{"제목":"대칭이동한 원의 방정식","힌트":"중심 $(1,\\ -3)$을 직선 $y=x$에 대해 대칭이동하면 어디인가?","식":["$(x+3)^{2}+(y-1)^{2}=r^{2}$"],"설명":"$(x,\\ y)\\to(y,\\ x)$이므로 중심은 $(-3,\\ 1)$이 된다. 반지름 $r$은 변하지 않는다.","확인":null,"스킬":"G4","고비":true},{"제목":"점을 대입해 $r$ 구하기","힌트":"원이 점 $(-2,\\ 2)$를 지나므로 대입하면 $r^{2}$는?","식":["$(-2+3)^{2}+(2-1)^{2}=r^{2}$","$r=\\sqrt{2}$"],"설명":"$r^{2}=2$이고 $r>0$이므로 양의 제곱근만 택한다.","확인":null,"스킬":"G4"}]},"tb-비상공수2-p058-5":{"길":"$x$축 대칭으로 직선을 바꾸고 접할 조건을 거리로 쓴다","단계":[{"제목":"$x$축 대칭이동한 직선","힌트":"$x$축에 대한 대칭이동은 어느 문자의 부호를 바꾸는가?","식":["$4x+3y+a=0$"],"설명":"$x$축 대칭이동은 $y$를 $-y$로 바꾼다.","확인":null,"스킬":"G4"},{"제목":"접하는 조건식","힌트":"중심 $(-2,\\ 5)$에서 직선까지의 거리가 반지름과 같다는 식은?","식":["$\\frac{|4\\cdot(-2)+3\\cdot5+a|}{\\sqrt{4^{2}+3^{2}}}=\\frac{|7+a|}{5}=2$"],"설명":"접하면 중심에서 직선까지의 거리가 반지름 $2$와 같다.","확인":null,"스킬":"G2","고비":true},{"제목":"$a$의 값","힌트":"$|7+a|=10$이면 $7+a$는 어떤 값들인가?","식":["$7+a=\\pm10$","$a=3$","$a=-17$"],"설명":"절댓값이 $10$인 수는 $10$과 $-10$이다.","확인":null,"스킬":"G2"}]},"tb-비상공수2-p058-6":{"길":"원의 넓이를 이등분하는 직선은 원의 중심을 지난다","단계":[{"제목":"직선 $l$ 구하기","힌트":"$x$축에 대해 대칭이동하면 $y$는 어떻게 바뀌는가?","식":["$l:\\ 3x-y=4$"],"설명":"$x$축 대칭이동은 $y$를 $-y$로 바꾼다.","확인":null,"스킬":"G4"},{"제목":"원 C의 중심","힌트":"원점 대칭이동은 중심의 좌표를 어떻게 바꾸는가?","식":["$\\mathrm{C}:\\ (x+3)^{2}+(y-k)^{2}=5$","$(-3,\\ k)$"],"설명":"원점 대칭이동은 $(x,\\ y)\\to(-x,\\ -y)$이므로 중심 $(3,\\ -k)$가 $(-3,\\ k)$로 바뀐다.","확인":null,"스킬":"G4"},{"제목":"넓이 이등분 조건으로 $k$ 구하기","힌트":"넓이를 이등분하는 직선은 원의 어떤 점을 지나는가?","식":["$3\\cdot(-3)-k=4$","$k=-13$"],"설명":"원의 넓이를 이등분하는 직선은 중심을 지난다. 중심 $(-3,\\ k)$를 $l$의 식에 대입한다.","확인":"-13","스킬":"G1","고비":true}]},"tb-비상공수2-p059-1-1":{"길":"대상이 분명히 정해지는지 따진 뒤 조건에 맞는 원소를 빠짐없이 쓴다","단계":[{"제목":"집합인지 판단","힌트":"누가 판단해도 같은 대상이 모이는가?","식":[],"설명":"약수는 기준이 분명해 누가 따져도 같은 대상이 모인다. 따라서 집합이므로 ○표이다.","확인":null,"스킬":"C4"},{"제목":"원소 모두 나열","힌트":"$15$를 나누어떨어지게 하는 자연수는 무엇인가?","식":["$\\{1,\\ 3,\\ 5,\\ 15\\}$"],"설명":"$15=3\\cdot5$이므로 $1$과 $15$ 자신까지 포함해 약수는 네 개이다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p059-1-2":{"길":"'잘하는'처럼 기준이 사람마다 다른 말은 집합이 되지 못한다","단계":[{"제목":"조건의 기준 점검","힌트":"'운동을 잘한다'를 누가 판단해도 같은 결과가 나오는가?","식":[],"설명":"'잘하는'의 기준은 사람마다 달라서 어떤 학생이 포함되는지 분명하지 않다.","확인":null,"스킬":"C4","고비":true},{"제목":"×표 결정","힌트":"대상이 분명하지 않으면 집합인가?","식":["$\\times$"],"설명":"대상이 분명하게 정해지지 않으므로 집합이 아니다. 집합이 아니므로 원소를 구하지 않는다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p059-2-1":{"길":"정수를 분모가 1인 분수로 쓸 수 있는지 살핀다","단계":[{"제목":"분수 꼴로 바꾸기","힌트":"$-5$를 (정수)/(0이 아닌 정수) 꼴로 쓰면?","식":["$-5=\\frac{-5}{1}$"],"설명":"정수는 분모를 $1$로 하는 분수로 나타낼 수 있다.","확인":null,"스킬":"N6","고비":true},{"제목":"기호 결정","힌트":"유리수는 어떤 꼴로 나타낼 수 있는 수인가?","식":["$-5\\in Q$"],"설명":"정수 두 개의 비로 나타낼 수 있으므로 유리수이다. 따라서 $Q$의 원소이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p059-2-2":{"길":"분수 꼴이면 음수여도 유리수라는 점을 확인한다","단계":[{"제목":"유리수의 꼴 확인","힌트":"$-\\frac{1}{9}$은 (정수)/(0이 아닌 정수) 꼴로 나타낼 수 있는가?","식":["$-\\frac{1}{9}=\\frac{-1}{9}$"],"설명":"분자가 정수이고 분모가 $0$이 아닌 정수이므로 유리수의 꼴이다.","확인":null,"스킬":"N6","고비":true},{"제목":"기호 결정","힌트":"유리수 전체의 집합 $Q$에 속하는가?","식":["$-\\frac{1}{9}\\in Q$"],"설명":"음수라도 분수로 나타낼 수 있으면 유리수이므로 $Q$의 원소이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p059-2-3":{"길":"$\\sqrt{2}$가 분수로 나타내어지는 수인지 판단한다","단계":[{"제목":"수의 종류 판단","힌트":"$\\sqrt{2}$를 (정수)/(정수) 꼴로 나타낼 수 있는가?","식":[],"설명":"$\\sqrt{2}$는 어떤 분수로도 나타낼 수 없는 무리수이다.","확인":null,"스킬":"N6","고비":true},{"제목":"기호 결정","힌트":"무리수는 유리수 전체의 집합 $Q$에 속하는가?","식":["$\\sqrt{2}\\notin Q$"],"설명":"유리수가 아니므로 $Q$의 원소가 아니다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p059-2-4":{"길":"근호가 있어도 먼저 계산해 유리수인지 본다","단계":[{"제목":"근호 계산","힌트":"제곱해서 $9$가 되는 양수는 무엇인가?","식":["$\\sqrt{9}=3$"],"설명":"$3^{2}=9$이고 $3>0$이므로 $\\sqrt{9}=3$이다.","확인":"3","스킬":"N6","고비":true},{"제목":"기호 결정","힌트":"계산한 값은 유리수인가?","식":["$\\sqrt{9}\\in Q$"],"설명":"$3=\\frac{3}{1}$이므로 유리수이다. 따라서 $Q$의 원소이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p059-3":{"길":"조건제시법을 원소나열법으로 바꿔 끝 값을 비교한다","단계":[{"제목":"①~④의 원소 나열","힌트":"①~④를 각각 원소나열법으로 바꾸면 어떤 집합인가?","식":["$\\{1,\\ 2,\\ 3,\\ \\cdots,\\ 9\\}$"],"설명":"②는 $9$ 이하, ③은 $10$ 미만, ④는 한 자리의 자연수이므로 모두 $1$부터 $9$까지의 자연수이다.","확인":null,"스킬":"C4"},{"제목":"⑤의 원소 나열","힌트":"$1<y<10$에서 $y=1$은 포함되는가?","식":["$\\{2,\\ 3,\\ \\cdots,\\ 9\\}$"],"설명":"$1<y$에는 등호가 없어 $1$이 빠진다. 따라서 ⑤만 나머지 넷과 다르다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p059-4":{"길":"보기를 하나씩 원소 여부와 원소의 개수로 따져 참거짓을 가린다","단계":[{"제목":"ㄱ, ㄴ 판정","힌트":"ㄱ에서 $3$은 집합 $\\{2,\\ 4,\\ 6\\}$의 원소인가? ㄴ에서 공집합에 원소가 있는가?","식":["$3\\notin\\{2,\\ 4,\\ 6\\}$","$0\\notin\\varnothing$"],"설명":"ㄱ은 $3$이 원소가 아니므로 거짓이다. ㄴ은 공집합에 원소가 하나도 없으므로 참이다.","확인":null,"스킬":"C3"},{"제목":"ㄷ, ㄹ 판정","힌트":"ㄷ에서 $10$은 $10$ 이하의 자연수인가? ㄹ에서 원소는 몇 개인가?","식":["$10\\in\\{1,\\ 2,\\ \\cdots,\\ 10\\}$","$n(\\{a,\\ b\\})=2$"],"설명":"ㄷ은 $10$이 원소이므로 $\\notin$이라는 말이 거짓이다. ㄹ은 원소가 $a$, $b$ 두 개이므로 참이다. 따라서 옳은 것은 ㄴ, ㄹ이다.","확인":null,"스킬":"C3","고비":true}]},"tb-비상공수2-p059-5":{"길":"'이하'와 '보다 작은'의 끝 값을 구분해 각 집합의 원소 수를 센다","단계":[{"제목":"$n(A)$ 구하기","힌트":"$30$ 이하의 홀수는 $1$부터 몇까지, 몇 개인가?","식":["$A=\\{1,\\ 3,\\ \\cdots,\\ 29\\}$","$n(A)=15$"],"설명":"$30$ 이하의 홀수는 $1$부터 $29$까지이며, $29=2\\cdot15-1$이므로 $15$개이다.","확인":"15","스킬":"P4"},{"제목":"$n(B)$ 구하기","힌트":"$100$보다 작은 $3$의 배수 중 가장 큰 수는 무엇인가?","식":["$B=\\{3,\\ 6,\\ \\cdots,\\ 99\\}$","$n(B)=33$"],"설명":"'보다 작은'이므로 $100$은 제외하고 $99=3\\cdot33$까지이다. 따라서 $33$개이다.","확인":"33","스킬":"P4","고비":true},{"제목":"$n(A)+n(B)$ 계산","힌트":"두 개수를 더하면 얼마인가?","식":["$15+33=48$"],"설명":"구한 두 원소의 개수를 더한다.","확인":"48","스킬":"P4"}]},"tb-비상공수2-p059-6":{"길":"곱을 빠짐없이 적은 뒤 같은 값은 한 번만 센다","단계":[{"제목":"곱 모두 구하기","힌트":"$x\\in A$, $y\\in B$의 모든 짝에 대해 $xy$는 몇 가지인가?","식":["$2,\\ 3,\\ 5,\\ 4,\\ 6,\\ 10,\\ 6,\\ 9,\\ 15$"],"설명":"$A$의 원소 $1$, $2$, $3$에 $B$의 원소 $2$, $3$, $5$를 차례로 곱하면 $3\\times3=9$개의 곱이 나온다.","확인":null,"스킬":"P4"},{"제목":"중복 제거한 집합 $C$","힌트":"같은 값이 두 번 나온 곱은 무엇인가?","식":["$C=\\{2,\\ 3,\\ 4,\\ 5,\\ 6,\\ 9,\\ 10,\\ 15\\}$"],"설명":"$2\\cdot3$과 $3\\cdot2$가 모두 $6$이므로 집합에서는 한 번만 쓴다.","확인":null,"스킬":"C6","고비":true},{"제목":"$n(C)$ 구하기","힌트":"$C$의 원소는 몇 개인가?","식":["$n(C)=8$"],"설명":"중복을 제거한 원소의 개수가 $n(C)$이다.","확인":"8","스킬":"P4"}]},"tb-비상공수2-p060-1":{"길":"원소와 집합 사이는 ∈, 집합과 집합 사이는 ⊂임을 기준으로 보기를 가른다","단계":[{"제목":"원소와 집합 사이의 기호 판정","힌트":"ㄱ, ㄴ, ㅁ에서 왼쪽이 원소인가 집합인가?","식":["$3\\in A$","$\\{2\\}\\subset A$","$5\\in B$"],"설명":"ㄱ은 $3$이 $A$의 원소이므로 참이다. ㄴ의 $\\{2\\}$는 집합이므로 $\\in$이 아니라 $\\subset$를 써야 해서 거짓이다. ㅁ의 $5$는 원소이므로 $\\subset$가 아니라 $\\in$를 써야 해서 거짓이다.","확인":null,"스킬":"C4","고비":true},{"제목":"집합 사이의 포함 관계 판정","힌트":"ㄷ, ㄹ에서 앞 집합의 원소가 모두 뒤 집합에 속하는가?","식":["$1\\notin B$","$B\\subset A$"],"설명":"ㄷ은 $A$의 원소 $1$이 $B$에 없으므로 $A\\subset B$가 아니어서 거짓이다. ㄹ은 $B$의 원소 $3$, $5$가 모두 $A$에 속하므로 참이다. 따라서 옳은 것은 ㄱ, ㄹ이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p060-2-1":{"길":"원소가 적은 집합의 원소가 모두 다른 쪽에 들어가는지 본다","단계":[{"제목":"원소의 포함 여부 확인","힌트":"$B$의 원소 $a$, $e$, $o$는 각각 $A$에 속하는가?","식":["$a\\in A,\\ e\\in A,\\ o\\in A$"],"설명":"$B$의 원소가 모두 $A$에 속한다.","확인":null,"스킬":"C4","고비":true},{"제목":"포함 관계 기호로 나타내기","힌트":"어느 집합이 어느 집합의 부분집합인가?","식":["$B\\subset A$"],"설명":"$B$의 모든 원소가 $A$에 속하므로 $B$는 $A$의 부분집합이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p060-2-2":{"길":"조건제시법을 원소나열법으로 바꾼 뒤 원소의 포함 여부를 비교한다","단계":[{"제목":"$B$의 원소 나열","힌트":"$5$ 이하인 자연수를 모두 쓰면?","식":["$B=\\{1,\\ 2,\\ 3,\\ 4,\\ 5\\}$"],"설명":"자연수는 $1$부터 시작하므로 $1$, $2$, $3$, $4$, $5$이다.","확인":null,"스킬":"C4","고비":true},{"제목":"포함 관계 기호로 나타내기","힌트":"$A$의 원소 $1$, $3$, $4$, $5$는 각각 $B$에 속하는가?","식":["$A\\subset B$"],"설명":"$A$의 원소가 모두 $B$에 속하고 $B$에는 $2$가 더 있으므로 $A$가 $B$의 부분집합이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p060-3":{"길":"집합 $A$의 원소를 구한 뒤 원소의 개수별로 부분집합을 빠짐없이 쓴다","단계":[{"제목":"집합 $A$의 원소 구하기","힌트":"$x(x-1)(x-2)=0$을 만족하는 $x$는?","식":["$A=\\{0,\\ 1,\\ 2\\}$"],"설명":"세 인수 중 하나가 $0$이면 곱이 $0$이므로 $x=0,\\ 1,\\ 2$이다.","확인":null,"스킬":"C4"},{"제목":"부분집합 나열","힌트":"원소가 0개, 1개, 2개, 3개인 부분집합을 차례로 쓰면?","식":["$\\varnothing,\\ \\{0\\},\\ \\{1\\},\\ \\{2\\}$","$\\{0,1\\},\\ \\{0,2\\},\\ \\{1,2\\}$","$\\{0,1,2\\}$"],"설명":"공집합과 $A$ 자신도 부분집합이다. 원소의 개수별로 나누어 쓰면 빠뜨리지 않는다.","확인":null,"스킬":"P4","고비":true},{"제목":"부분집합의 개수","힌트":"원소가 $3$개인 집합의 부분집합 개수는 $2$의 몇 제곱인가?","식":["$2^{3}=8$"],"설명":"원소가 $n$개인 집합의 부분집합은 $2^{n}$개이다. 나열한 개수도 $1+3+3+1=8$로 같다.","확인":"8","스킬":"P4"}]},"tb-비상공수2-p060-4":{"길":"$1$, $2$를 뺀 나머지 원소로 만든 부분집합의 개수와 같다","단계":[{"제목":"남는 원소로 이루어진 집합","힌트":"$1$, $2$를 원소로 갖지 않으려면 어떤 원소들로만 만들어야 하는가?","식":["$\\{3,\\ 4,\\ 5,\\ 6\\}$"],"설명":"구하는 집합은 $A$에서 $1$, $2$를 뺀 $\\{3,\\ 4,\\ 5,\\ 6\\}$의 부분집합과 같다.","확인":null,"스킬":"P4","고비":true},{"제목":"부분집합의 개수","힌트":"원소가 $4$개인 집합의 부분집합은 몇 개인가?","식":["$2^{4}=16$"],"설명":"원소가 $n$개인 집합의 부분집합은 $2^{n}$개이다.","확인":"16","스킬":"P4"}]},"tb-비상공수2-p060-5":{"길":"조건을 풀어 원소를 나열한 뒤 두 집합의 원소가 같은지 비교한다","단계":[{"제목":"(1) 두 집합 비교","힌트":"두 집합의 원소가 모두 같은가?","식":["$\\{-1,\\ 0,\\ 1\\}\\ne\\{1,\\ 2,\\ 3\\}$"],"설명":"$A$에는 $-1$, $0$이 있지만 $B$에는 없으므로 서로 다르다.","확인":null,"스킬":"C4"},{"제목":"(2) 방정식을 풀어 $B$ 구하기","힌트":"$x^{2}-4x+3=0$의 해는?","식":["$(x-1)(x-3)=0$","$B=\\{1,\\ 3\\}$"],"설명":"인수분해하면 $x=1$ 또는 $x=3$이다. $B=\\{1,\\ 3\\}$이 $A$와 같다.","확인":null,"스킬":"C4","고비":true},{"제목":"(3) 원소 나열 후 비교","힌트":"$10$ 이하의 홀수를 모두 쓰면?","식":["$A=\\{1,\\ 3,\\ 5,\\ 7,\\ 9\\}=B$"],"설명":"$10$ 이하의 홀수는 $1$, $3$, $5$, $7$, $9$이므로 $B$와 같다. 따라서 같은 것은 (2), (3)이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p060-6":{"길":"포함 관계가 성립하면서 두 집합이 서로 다른지 하나씩 확인한다","단계":[{"제목":"(1) 약수의 집합 비교","힌트":"$6$의 약수를 모두 쓰면 $B$와 어떤 관계인가?","식":["$A=\\{1,\\ 2,\\ 3,\\ 6\\}=B$"],"설명":"$A$와 $B$가 같은 집합이므로 진부분집합이 아니다. 진부분집합은 $A\\subset B$이면서 $A\\ne B$이다.","확인":null,"스킬":"C4"},{"제목":"(2) 홀수의 집합 비교","힌트":"홀수인 한 자리의 자연수를 모두 쓰면 $A$와 어떤 관계인가?","식":["$B=\\{1,\\ 3,\\ 5,\\ 7,\\ 9\\}$","$A\\subset B,\\ A\\ne B$"],"설명":"$A$의 원소는 모두 $B$에 속하고 $B$에는 $7$, $9$가 더 있다. 따라서 $A$는 $B$의 진부분집합이다.","확인":null,"스킬":"C4"},{"제목":"(3) 부등식을 풀어 집합 비교","힌트":"$x^{2}-9<0$을 만족하는 정수와 $|x|\\le1$을 만족하는 정수는 각각 무엇인가?","식":["$A=\\{-2,\\ -1,\\ 0,\\ 1,\\ 2\\}$","$B=\\{-1,\\ 0,\\ 1\\}$"],"설명":"$-3<x<3$이므로 $A$는 정수 다섯 개이고, $-1\\le x\\le1$이므로 $B$는 세 개이다. $A$의 $-2$가 $B$에 없어 $A\\not\\subset B$이므로 진부분집합이 아니다. 따라서 진부분집합인 것은 (2)뿐이다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p061-1-1":{"길":"공통 원소로 교집합을 만들고 합집합은 겹치는 원소를 한 번만 쓴다","단계":[{"제목":"교집합 구하기","힌트":"$A$와 $B$에 모두 속하는 원소는?","식":["$A\\cap B=\\{a,\\ e\\}$"],"설명":"두 집합에 공통으로 들어 있는 원소는 $a$, $e$이다.","확인":null,"스킬":"C4"},{"제목":"합집합 구하기","힌트":"$A$ 또는 $B$에 속하는 원소를 겹치지 않게 모두 쓰면?","식":["$A\\cup B=\\{a,\\ b,\\ c,\\ d,\\ e,\\ i,\\ o,\\ u\\}$"],"설명":"공통 원소 $a$, $e$는 한 번만 쓴다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p061-1-2":{"길":"$|x|\\le2$인 정수를 음수와 $0$까지 빠짐없이 쓴 뒤 교집합·합집합을 구한다","단계":[{"제목":"$B$의 원소 나열","힌트":"$|x|\\le2$를 부등식으로 풀어 쓰면?","식":["$-2\\le x\\le2$","$B=\\{-2,\\ -1,\\ 0,\\ 1,\\ 2\\}$"],"설명":"$|x|\\le2$는 $-2\\le x\\le2$와 같다. 음수와 $0$을 빠뜨리지 않는다.","확인":null,"스킬":"C4","고비":true},{"제목":"교집합 구하기","힌트":"$A$와 $B$에 모두 속하는 원소는?","식":["$A\\cap B=\\{1,\\ 2\\}$"],"설명":"$A=\\{1,\\ 2,\\ 3\\}$과 $B$의 공통 원소를 찾는다.","확인":null,"스킬":"C4"},{"제목":"합집합 구하기","힌트":"두 집합의 원소를 겹치지 않게 모두 쓰면?","식":["$A\\cup B=\\{-2,\\ -1,\\ 0,\\ 1,\\ 2,\\ 3\\}$"],"설명":"공통 원소 $1$, $2$는 한 번만 쓴다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p061-1-3":{"길":"$\\le$와 $<$로 끝 값이 들어가는지 먼저 정하고 두 집합을 나열한다","단계":[{"제목":"$A$, $B$의 원소 나열","힌트":"$-1\\le x<4$와 $0<x<5$를 만족하는 정수를 각각 쓰면?","식":["$A=\\{-1,\\ 0,\\ 1,\\ 2,\\ 3\\}$","$B=\\{1,\\ 2,\\ 3,\\ 4\\}$"],"설명":"$A$는 $-1$이 포함되고 $4$는 제외된다. $B$는 $0$과 $5$가 모두 제외된다.","확인":null,"스킬":"C4","고비":true},{"제목":"교집합 구하기","힌트":"두 집합에 모두 속하는 원소는?","식":["$A\\cap B=\\{1,\\ 2,\\ 3\\}$"],"설명":"$A$와 $B$에 공통으로 들어 있는 원소를 찾는다.","확인":null,"스킬":"C4"},{"제목":"합집합 구하기","힌트":"두 집합의 원소를 겹치지 않게 모두 쓰면?","식":["$A\\cup B=\\{-1,\\ 0,\\ 1,\\ 2,\\ 3,\\ 4\\}$"],"설명":"공통 원소 $1$, $2$, $3$은 한 번만 쓴다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p061-2":{"길":"교집합의 원소와 $A$에 없는 합집합의 원소로 $B$를 채운다","단계":[{"제목":"교집합에서 알 수 있는 $B$의 원소","힌트":"$A\\cap B$의 원소는 $B$에 속하는가?","식":["$3\\in B,\\ 4\\in B$"],"설명":"교집합의 원소는 두 집합에 모두 속한다. $A$의 원소 $1$, $2$는 $A\\cap B$에 없으므로 $B$에 속하지 않는다.","확인":null,"스킬":"C4"},{"제목":"$A$에 없는 합집합의 원소","힌트":"$A\\cup B$의 원소 중 $A$에 없는 것은 어느 집합에 속해야 하는가?","식":["$5\\in B,\\ 6\\in B$"],"설명":"$5$, $6$은 $A\\cup B$에 있지만 $A$에는 없으므로 $B$에 속해야 한다.","확인":null,"스킬":"C4","고비":true},{"제목":"집합 $B$ 정리","힌트":"$B$에 속하는 원소를 모두 모으면?","식":["$B=\\{3,\\ 4,\\ 5,\\ 6\\}$"],"설명":"$B$의 원소는 $3$, $4$, $5$, $6$뿐이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p061-3":{"길":"전체 인원이 합집합임을 이용해 둘 다 좋아하는 학생 수를 구한다","단계":[{"제목":"합집합의 인원 파악","힌트":"아무것도 좋아하지 않는 학생이 없으면 축구 또는 배드민턴을 좋아하는 학생은 몇 명인가?","식":["$n(A\\cup B)=26$"],"설명":"축구를 좋아하는 학생의 집합을 $A$, 배드민턴을 좋아하는 학생의 집합을 $B$라 하면 전체 학생이 $A\\cup B$이다.","확인":null,"스킬":"C7"},{"제목":"인원 사이의 관계식","힌트":"$n(A)+n(B)$에서 둘 다 좋아하는 학생은 몇 번 세어지는가?","식":["$n(A\\cup B)=n(A)+n(B)-n(A\\cap B)$"],"설명":"두 인원을 더하면 둘 다 좋아하는 학생이 두 번 세어지므로 한 번 빼야 한다.","확인":null,"스킬":"C4","고비":true},{"제목":"둘 다 좋아하는 학생 수","힌트":"관계식에 $22$, $18$, $26$을 대입하면?","식":["$26=22+18-n(A\\cap B)$","$n(A\\cap B)=14$"],"설명":"$22+18=40$이므로 $n(A\\cap B)=40-26$이다.","확인":"14","스킬":"C4"}]},"tb-비상공수2-p061-4":{"길":"분배법칙으로 식을 줄여 공통부분의 원소만 구한다","단계":[{"제목":"분배법칙으로 식 간단히 하기","힌트":"$(A\\cup B)\\cap(A\\cup C)$에서 공통으로 들어 있는 집합은 무엇인가?","식":["$(A\\cup B)\\cap(A\\cup C)=A\\cup(B\\cap C)$"],"설명":"합집합과 교집합의 분배법칙을 쓰면 $A$가 공통으로 묶인다.","확인":null,"스킬":"C4","고비":true},{"제목":"$B\\cap C$ 구하기","힌트":"$3$의 배수이면서 $5$의 배수인 $30$ 이하의 수는?","식":["$B\\cap C=\\{15,\\ 30\\}$"],"설명":"$C$의 원소 중 $3$의 배수는 $15$, $30$이다.","확인":null,"스킬":"C4"},{"제목":"$A$와 합집합 만들기","힌트":"$A$에 $15$, $30$을 합치면 원소는 어떻게 되는가?","식":["$A\\cup\\{15,\\ 30\\}=\\{2,\\ 4,\\ 6,\\ \\cdots,\\ 14,\\ 15,\\ 16,\\ \\cdots,\\ 28,\\ 30\\}$"],"설명":"$30$은 이미 $A$의 원소이므로 새로 더해지는 것은 $15$뿐이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p061-5-1":{"길":"전체집합에서 $A$의 원소를 빼되 $10$을 빠뜨리지 않는다","단계":[{"제목":"전체집합의 원소 나열","힌트":"$10$ 이하의 자연수를 모두 쓰면?","식":["$U=\\{1,\\ 2,\\ 3,\\ \\cdots,\\ 10\\}$"],"설명":"$A$, $B$에는 없지만 $10$도 $U$의 원소이다.","확인":null,"스킬":"C4","고비":true},{"제목":"$U-A$ 구하기","힌트":"$U$의 원소 중 $A$에 속하지 않는 것은?","식":["$U-A=\\{2,\\ 4,\\ 6,\\ 8,\\ 10\\}$"],"설명":"$U$에서 $A$의 원소 $1$, $3$, $5$, $7$, $9$를 뺀다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p061-5-2":{"길":"$B$의 원소 중 $A$에도 속하는 것만 제외한다","단계":[{"제목":"$B$와 $A$의 공통 원소","힌트":"$B$의 원소 중 $A$에도 속하는 것은?","식":["$A\\cap B=\\{3\\}$"],"설명":"$B=\\{2,\\ 3,\\ 4,\\ 6,\\ 8\\}$ 중 $A$에 있는 원소는 $3$뿐이다.","확인":null,"스킬":"C4","고비":true},{"제목":"$B-A$ 구하기","힌트":"$B$에서 공통 원소를 빼면?","식":["$B-A=\\{2,\\ 4,\\ 6,\\ 8\\}$"],"설명":"$B-A$는 $B$의 원소 중 $A$에 속하지 않는 것으로 이루어진다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p061-5-3":{"길":"$B$의 여집합을 구하고 다시 여집합을 취한다","단계":[{"제목":"$B$의 여집합","힌트":"$U$의 원소 중 $B$에 속하지 않는 것은?","식":["$B^{C}=\\{1,\\ 5,\\ 7,\\ 9,\\ 10\\}$"],"설명":"$U=\\{1,\\ 2,\\ \\cdots,\\ 10\\}$에서 $B$의 원소 $2$, $3$, $4$, $6$, $8$을 뺀다.","확인":null,"스킬":"C4"},{"제목":"여집합의 여집합","힌트":"$B^{C}$에 속하지 않는 $U$의 원소는?","식":["$(B^{C})^{C}=\\{2,\\ 3,\\ 4,\\ 6,\\ 8\\}=B$"],"설명":"$U$에서 $B^{C}$의 원소를 빼면 원래의 $B$가 남는다. 여집합의 여집합은 자기 자신이다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p061-5-4":{"길":"$B^{C}$를 먼저 구하고 $A$와 공통인 원소를 찾는다","단계":[{"제목":"$B$의 여집합","힌트":"$U$의 원소 중 $B$에 속하지 않는 것은?","식":["$B^{C}=\\{1,\\ 5,\\ 7,\\ 9,\\ 10\\}$"],"설명":"$U$에서 $B$의 원소 $2$, $3$, $4$, $6$, $8$을 뺀다. $10$도 포함된다.","확인":null,"스킬":"C4","고비":true},{"제목":"$A$와의 교집합","힌트":"$A$의 원소 중 $B^{C}$에도 속하는 것은?","식":["$A\\cap B^{C}=\\{1,\\ 5,\\ 7,\\ 9\\}$"],"설명":"$A$의 원소 $3$은 $B$에 속하므로 제외된다. 이 집합은 $A-B$와 같다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p061-6":{"길":"$A\\cup B$를 겹치지 않는 두 부분 $A-B$와 $B$로 나눈다","단계":[{"제목":"합집합을 겹치지 않게 나누기","힌트":"$A\\cup B$를 $A-B$와 어떤 집합으로 나눌 수 있는가?","식":["$A\\cup B=(A-B)\\cup B$","$n(A\\cup B)=n(A-B)+n(B)$"],"설명":"$A-B$와 $B$는 공통 원소가 없으므로 개수를 그대로 더할 수 있다.","확인":null,"스킬":"C4","고비":true},{"제목":"$n(A\\cup B)$ 계산","힌트":"$n(A-B)$와 $n(B)$를 더하면?","식":["$n(A\\cup B)=17+15=32$"],"설명":"$n(A)=30$은 이 계산에 필요하지 않다.","확인":"32","스킬":"C4"}]},"tb-비상공수2-p061-7":{"길":"합집합과 교집합 인원을 차례로 구해 한 영화만 본 학생 수를 센다","단계":[{"제목":"두 영화 중 하나 이상 본 학생 수","힌트":"전체에서 어느 것도 보지 않은 학생을 빼면?","식":["$n(A\\cup B)=110-17=93$"],"설명":"영화 $\\mathrm{A}$를 본 학생의 집합을 $A$, 영화 $\\mathrm{B}$를 본 학생의 집합을 $B$라 하면 하나 이상 본 학생이 $A\\cup B$이다.","확인":"93","스킬":"C7"},{"제목":"두 영화를 모두 본 학생 수","힌트":"$n(A)+n(B)$에서 $n(A\\cup B)$를 빼면 무엇이 남는가?","식":["$n(A\\cap B)=39+67-93=13$"],"설명":"$n(A\\cup B)=n(A)+n(B)-n(A\\cap B)$에서 $n(A\\cap B)$를 구한다.","확인":"13","스킬":"C4","고비":true},{"제목":"한 영화만 본 학생 수","힌트":"$A$만 본 학생과 $B$만 본 학생을 각각 구해 더하면?","식":["$(39-13)+(67-13)=26+54=80$"],"설명":"각 영화를 본 학생에서 둘 다 본 학생을 빼면 그 영화만 본 학생 수이다.","확인":"80","스킬":"C4"}]},"tb-비상공수2-p062-1-1":{"길":"참, 거짓을 가릴 수 있는 문장인지 보고 그 뒤에 참거짓을 판별한다","단계":[{"제목":"명제인지 판단","힌트":"이 문장은 참인지 거짓인지 분명하게 가릴 수 있는가?","식":[],"설명":"정사각형의 정의로 참, 거짓을 분명히 가릴 수 있다. 따라서 명제이므로 ○표이다.","확인":null,"스킬":"C4"},{"제목":"참, 거짓 판별","힌트":"정사각형의 네 변의 길이는 서로 어떤 관계인가?","식":[],"설명":"정사각형은 네 변의 길이가 모두 같으므로 주어진 문장은 참이다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p062-1-2":{"길":"'큰'처럼 기준이 없는 말이 들어가면 참, 거짓을 가릴 수 없다","단계":[{"제목":"'큰'의 기준 점검","힌트":"누가 판단해도 $100$이 큰 수인지 같은 결과가 나오는가?","식":[],"설명":"'큰 수'의 기준이 분명하지 않아 사람마다 판단이 달라질 수 있다.","확인":null,"스킬":"C4","고비":true},{"제목":"×표 결정","힌트":"참, 거짓을 판별할 수 없는 문장은 명제인가?","식":["$\\times$"],"설명":"참, 거짓을 판별할 수 없으므로 명제가 아니다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p062-1-3":{"길":"$x$의 값에 따라 참, 거짓이 달라지는지 값을 넣어 확인한다","단계":[{"제목":"$x$의 값에 따른 변화 확인","힌트":"$x$에 서로 다른 값을 넣으면 등식이 항상 같은 결과가 되는가?","식":["$2\\cdot(-2)+4=0$","$2\\cdot0+4\\ne0$"],"설명":"$x=-2$이면 등식이 성립하고 $x=0$이면 성립하지 않는다. $x$의 값에 따라 참, 거짓이 달라진다.","확인":null,"스킬":"C4","고비":true},{"제목":"×표 결정","힌트":"문자의 값에 따라 참, 거짓이 달라지는 식은 명제인가 조건인가?","식":["$\\times$"],"설명":"참, 거짓이 하나로 정해지지 않으므로 명제가 아니라 조건이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p062-1-4":{"길":"$8$의 약수를 나열해 판별하며 거짓이어도 명제임을 확인한다","단계":[{"제목":"$8$의 약수 구하기","힌트":"$8$을 나누어떨어지게 하는 자연수는?","식":["$1,\\ 2,\\ 4,\\ 8$"],"설명":"$8=2^{3}$이므로 약수는 네 개이다.","확인":null,"스킬":"C4"},{"제목":"명제인지 판단하고 참거짓 판별","힌트":"$3$은 약수 목록에 있는가? 거짓이면 명제가 아닌가?","식":["$3\\notin\\{1,\\ 2,\\ 4,\\ 8\\}$"],"설명":"$3$은 약수가 아니므로 거짓이다. 참, 거짓을 판별할 수 있으면 거짓이어도 명제이므로 ○표이다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p062-2-1":{"길":"전체집합의 원소를 하나씩 보며 조건 $q$가 참인 원소를 모은다","단계":[{"제목":"조건 $q$가 참인 원소 고르기","힌트":"$U$의 원소 중 홀수는 무엇인가?","식":["$1,\\ 3,\\ 5,\\ 7,\\ 9$"],"설명":"$U$의 원소를 하나씩 보며 홀수인지 판단한다.","확인":null,"스킬":"C4","고비":true},{"제목":"진리집합으로 나타내기","힌트":"조건을 참이 되게 하는 원소를 모두 모은 집합을 무엇이라 하는가?","식":["$\\{1,\\ 3,\\ 5,\\ 7,\\ 9\\}$"],"설명":"전체집합의 원소 중 조건을 참이 되게 하는 원소의 집합이 진리집합이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p062-2-2":{"길":"$p$의 진리집합을 구한 뒤 그 여집합이 $\\sim p$의 진리집합임을 쓴다","단계":[{"제목":"$p$의 진리집합","힌트":"$U$의 원소 중 $3$의 배수는?","식":["$P=\\{3,\\ 6,\\ 9\\}$"],"설명":"$U$의 원소를 하나씩 보며 $3$의 배수를 고른다.","확인":null,"스킬":"C4"},{"제목":"$\\sim p$의 진리집합","힌트":"$\\sim p$가 참이 되는 원소는 $P$에 속하는가?","식":["$P^{C}=\\{1,\\ 2,\\ 4,\\ 5,\\ 7,\\ 8,\\ 10\\}$"],"설명":"$\\sim p$의 진리집합은 $P$의 여집합이다. $U$에서 $3$, $6$, $9$를 빼며 $10$을 빠뜨리지 않는다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p062-3-1":{"길":"두 조건의 진리집합을 나열해 벗어나는 원소를 반례로 찾는다","단계":[{"제목":"두 조건의 진리집합","힌트":"$8$의 약수와 $4$의 약수를 각각 쓰면?","식":["$P=\\{1,\\ 2,\\ 4,\\ 8\\}$","$Q=\\{1,\\ 2,\\ 4\\}$"],"설명":"$x$가 $8$의 약수라는 조건의 진리집합을 $P$, $4$의 약수라는 조건의 진리집합을 $Q$라 한다.","확인":null,"스킬":"C4"},{"제목":"포함 관계 확인과 반례","힌트":"$P$의 원소 중 $Q$에 속하지 않는 것이 있는가?","식":["$8\\in P,\\ 8\\notin Q$","$x=8$"],"설명":"$P\\subset Q$이어야 명제가 참인데 $8$이 $P$에만 속한다. 따라서 거짓이고 반례는 $x=8$이다.","확인":null,"스킬":"C3","고비":true}]},"tb-비상공수2-p062-3-2":{"길":"$\\ne$가 있는 명제는 대우로 바꿔 참, 거짓을 판단한다","단계":[{"제목":"대우 만들기","힌트":"$p\\to q$의 대우는 $\\sim q\\to\\sim p$이다. $\\ne$를 부정하면?","식":["$x^{2}+y^{2}=0\\ \\Rightarrow\\ x+y=0$"],"설명":"결론의 부정이 가정이 되고 가정의 부정이 결론이 된다. $\\ne$의 부정은 $=$이다.","확인":null,"스킬":"C4"},{"제목":"대우의 참, 거짓 판별","힌트":"실수의 제곱은 $0$ 이상인데, 두 제곱의 합이 $0$이면 각각은 얼마인가?","식":["$x^{2}=0,\\ y^{2}=0$","$x=y=0$"],"설명":"실수일 때 $x^{2}\\ge0$, $y^{2}\\ge0$이므로 합이 $0$이려면 둘 다 $0$이다. 따라서 $x+y=0$이 되어 대우는 참이다.","확인":null,"스킬":"C4","고비":true},{"제목":"처음 명제의 참, 거짓","힌트":"대우가 참이면 원래 명제는 어떠한가?","식":[],"설명":"어떤 명제와 그 대우는 참, 거짓이 같다. 대우가 참이므로 주어진 명제도 참이다.","확인":null,"스킬":"C4"}]},"tb-비상공수2-p062-3-3":{"길":"곱은 짝수이지만 한쪽이 홀수인 자연수 쌍을 찾아 반례로 삼는다","단계":[{"제목":"반례 후보 찾기","힌트":"곱이 짝수이면서 둘 중 하나는 홀수인 자연수 쌍은?","식":["$xy=1\\cdot2=2$"],"설명":"두 수 중 하나만 짝수여도 곱은 짝수가 된다. $x=1$, $y=2$이면 곱 $2$는 짝수이다.","확인":null,"스킬":"C3","고비":true},{"제목":"결론이 성립하지 않음 확인","힌트":"$x=1$, $y=2$에서 '모두 짝수'가 성립하는가?","식":["$x=1,\\ y=2$"],"설명":"가정은 참이지만 $x=1$이 홀수라 결론이 거짓이다. 반례가 하나 있으므로 명제는 거짓이다.","확인":null,"스킬":"C3"}]},"tb-비상공수2-p062-4":{"길":"$p\\to q$가 참이면 진리집합 $P$가 $Q$에 포함됨을 부등식으로 옮긴다","단계":[{"제목":"진리집합의 포함 관계","힌트":"$p\\to q$가 참이면 두 진리집합 $P$, $Q$ 사이에는 어떤 관계가 있는가?","식":["$P=\\{x\\mid-3\\le x\\le3\\}\\subset Q=\\{x\\mid-a<x<a\\}$"],"설명":"$p\\to q$가 참이면 $p$의 진리집합 $P$가 $q$의 진리집합 $Q$의 부분집합이다.","확인":null,"스킬":"C4"},{"제목":"양 끝에서 $a$의 조건 구하기","힌트":"$Q$는 등호가 없다. $-3$과 $3$이 모두 $Q$에 들어가려면?","식":["$-a<-3,\\ \\ 3<a$","$a>3$"],"설명":"$Q$에는 양 끝값이 포함되지 않으므로 $a=3$이면 $-3$, $3$이 빠진다. 따라서 $a$는 $3$보다 커야 한다.","확인":null,"스킬":"C4","고비":true},{"제목":"자연수 $a$의 최솟값","힌트":"$3$보다 큰 자연수 중 가장 작은 수는?","식":["$a=4$"],"설명":"$a>3$을 만족하는 자연수 중 가장 작은 수가 최솟값이다.","확인":"4","스킬":"C4"}]},"tb-비상공수2-p062-5":{"길":"P를 Q 안에 그리고 보기마다 반례 집합을 찾아 거른다","단계":[{"제목":"참인 명제를 포함 관계로 바꾸기","힌트":"$p\\longrightarrow q$가 참이면 $P$와 $Q$ 사이에 어떤 포함 관계가 성립하는가?","식":["$P\\subset Q$"],"설명":"명제 $p\\longrightarrow q$가 참이면 진리집합 사이에 $P\\subset Q$가 성립한다. 벤 다이어그램에서 $P$를 $Q$ 안에 그리고 보기를 판단한다.","확인":null,"스킬":"C4"},{"제목":"반례 집합으로 보기 거르기","힌트":"$P\\subset Q$를 만족하는 구체적인 집합을 하나 잡으면 어느 보기가 깨지는가?","식":["$U=\\{1,\\ 2,\\ 3\\}$, $P=\\{1\\}$, $Q=\\{1,\\ 2\\}$","$P^{C}=\\{2,\\ 3\\}$, $Q^{C}=\\{3\\}$"],"설명":"이 집합에서 $P\\cup Q=\\{1,\\ 2\\}$는 $P^{C}$와 다르므로 ㄱ은 거짓이고, $P\\cap Q=P\\ne Q$이므로 ㄴ도 거짓이다. $P^{C}\\cap Q=\\{2\\}\\ne Q$이므로 ㄷ이 거짓이고, $P^{C}\\cap Q^{C}=\\{3\\}\\ne\\varnothing$이므로 ㅁ도 거짓이다. 반례가 하나라도 있으면 항상 옳은 보기가 아니다.","확인":null,"스킬":"C3"},{"제목":"남은 보기가 항상 성립함을 확인","힌트":"$P\\subset Q$이면 $P^{C}\\cup Q$는 $P^{C}\\cup P$를 포함하는가?","식":["$P^{C}\\cup Q\\supset P^{C}\\cup P=U$"],"설명":"$P\\subset Q$이므로 $P^{C}\\cup Q$는 $P^{C}\\cup P$를 포함한다. $P^{C}\\cup P=U$이므로 $P^{C}\\cup Q=U$가 항상 성립하고, 항상 옳은 것은 ㄹ이다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p062-6":{"길":"'어떤'은 하나만 찾으면 참, '모든'은 반례 하나면 거짓","단계":[{"제목":"'어떤' 명제 (2) 확인","힌트":"$x^{2}=2x$를 만족하는 실수 $x$가 하나라도 있는가?","식":["$x^{2}-2x=0$","$x=0$ 또는 $x=2$"],"설명":"'어떤' 명제는 조건을 만족하는 값이 하나라도 있으면 참이다. $x=0$이 조건을 만족하므로 (2)는 참이다.","확인":null,"스킬":"C4"},{"제목":"'모든' 명제 (1), (3) 확인","힌트":"모든 실수에서 $x^{2}$과 $|x|^{2}$은 같은가?","식":["$|x|^{2}=x^{2}$"],"설명":"실수 $x$의 절댓값을 제곱하면 $x^{2}$과 같으므로 (1)은 참이다. 정사각형은 네 각이 모두 직각이므로 직사각형이고, (3)도 참이다.","확인":null,"스킬":"C4"},{"제목":"(4)가 성립하는 실수 찾기","힌트":"제곱해서 음수가 되는 실수가 있는가?","식":["$x^{2}\\ge0$"],"설명":"모든 실수 $x$에 대하여 $x^{2}\\ge0$이므로 $x^{2}<0$인 실수는 없다. 따라서 (4)는 거짓이다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p063-1":{"길":"명제마다 반례로 거짓을 가려내고, 역도 같은 방법으로 확인한다","단계":[{"제목":"ㄱ, ㄴ의 명제와 역 확인","힌트":"ㄱ에서 $x^{2}=y^{2}$이어도 $x=y$가 아닌 값이 있는가?","식":["ㄱ $x=1,\\ y=-1$","ㄴ $x=2$"],"설명":"ㄱ은 $x=1$, $y=-1$일 때 $x^{2}-y^{2}=0$이지만 $x\\ne y$이므로 거짓이다. ㄴ은 $x=2$일 때 $x^{2}-4=0$이지만 $x+2\\ne0$이므로 거짓이다. 명제가 거짓이므로 ㄱ, ㄴ은 답이 아니다.","확인":null,"스킬":"C3"},{"제목":"ㄷ의 역 확인","힌트":"$xy>0$이어도 $x<0$이고 $y<0$이 아닌 경우가 있는가?","식":["$x=1,\\ y=1$"],"설명":"ㄷ의 역은 '$xy>0$이면 $x<0$이고 $y<0$이다.'이다. $x=1$, $y=1$이면 $xy>0$이지만 $x<0$이 아니므로 역이 거짓이다. 따라서 ㄷ은 답이 아니다.","확인":null,"스킬":"C3"},{"제목":"ㄹ의 명제와 역 확인","힌트":"$x$, $y$가 양수일 때 $x^{2}=y^{2}$이면 $x=y$인가?","식":["$x^{2}-y^{2}=(x-y)(x+y)=0$","$x+y>0$ 이므로 $x=y$"],"설명":"$x=y$이면 $x^{2}=y^{2}$이므로 명제는 참이다. 역은 $x^{2}-y^{2}=(x-y)(x+y)=0$에서 $x+y>0$이므로 $x-y=0$, 즉 $x=y$가 되어 참이다. 명제와 역이 모두 참인 것은 ㄹ이다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p063-2":{"길":"Q⊂P를 q→p로 읽고, 참인 명제의 대우도 참임을 쓴다","단계":[{"제목":"포함 관계를 명제로 바꾸기","힌트":"$Q\\subset P$이면 어느 방향의 명제가 참인가?","식":["$Q\\subset P\\ \\Longrightarrow\\ q\\longrightarrow p$"],"설명":"진리집합이 $Q\\subset P$이면 $q$를 만족하는 모든 원소가 $p$를 만족한다. 따라서 명제 $q\\longrightarrow p$가 참이다.","확인":null,"스킬":"C4"},{"제목":"대우와 보기 대조","힌트":"$q\\longrightarrow p$의 대우는 무엇인가?","식":["$\\sim p\\longrightarrow\\sim q$"],"설명":"참인 명제의 대우는 항상 참이므로 $q\\longrightarrow p$의 대우 $\\sim p\\longrightarrow\\sim q$도 참이고, 이는 ㄷ이다. ㄱ은 $P\\subset Q$, ㄴ은 $P^{C}\\subset Q$, ㄹ은 $Q\\subset P^{C}$이어야 참이므로 $Q\\subset P$만으로는 알 수 없다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p063-3":{"길":"결론에 '또는'이 있으니 대우로 바꿔 '이고' 꼴로 푼다","단계":[{"제목":"대우 만들기","힌트":"'$a<k$ 또는 $b<-1$'의 부정은 어떻게 쓰는가?","식":["$a\\ge k$ 이고 $b\\ge-1$ 이면 $a+b\\ge5$"],"설명":"결론 '$a<k$ 또는 $b<-1$'의 부정은 '$a\\ge k$ 이고 $b\\ge-1$'이고, 가정 '$a+b<5$'의 부정은 '$a+b\\ge5$'이다. 원 명제가 참이면 대우도 참이므로 이 대우가 참이 되는 $k$를 구하면 된다.","확인":null,"스킬":"C4","고비":true},{"제목":"합의 최솟값 구하기","힌트":"$a\\ge k$, $b\\ge-1$의 양변을 더하면 $a+b$는 얼마 이상인가?","식":["$a+b\\ge k+(-1)=k-1$"],"설명":"두 부등식을 변끼리 더하면 $a+b\\ge k-1$이다. 등호는 $a=k$, $b=-1$일 때 성립하므로 $a+b$의 최솟값은 $k-1$이다.","확인":null,"스킬":"C1"},{"제목":"항상 5 이상이 될 조건","힌트":"$a+b$의 최솟값이 5 이상이 되려면 $k$는 얼마 이상이어야 하는가?","식":["$k-1\\ge5$","$k\\ge6$"],"설명":"$a\\ge k$, $b\\ge-1$인 모든 $a$, $b$에서 $a+b\\ge5$가 성립하려면 최솟값 $k-1$이 5 이상이어야 한다. 따라서 $k\\ge6$이고 $k$의 최솟값은 6이다.","확인":"6","스킬":"C1"}]},"tb-비상공수2-p063-4":{"길":"충분조건만 = P⊊Q — 진리집합을 구해 포함 관계를 본다","단계":[{"제목":"(1), (2), (4)의 진리집합 비교","힌트":"세 경우 모두 $P$가 $Q$에 포함되면서 $Q$보다 작은가?","식":["(1) $Q\\subset P$","(2) $P=Q=\\{1,\\ 3\\}$","(4) $P=\\{0,\\ 1\\}\\supset Q=\\{1\\}$"],"설명":"(1)은 $x>2$이면 $x>-1$이므로 $Q\\subset P$이다. (2)는 $|x-2|=1$과 $x^{2}-4x+3=0$의 해가 모두 1, 3이어서 $P=Q$이고, (4)는 $x^{2}=x$의 해가 0, 1이어서 $Q\\subset P$이다. 세 경우 모두 $P$가 $Q$보다 작은 집합이 아니므로 충분조건만 되는 경우가 아니다.","확인":null,"스킬":"C4"},{"제목":"(3)의 포함 관계 확인","힌트":"$xy=|xy|$는 $xy$가 어떤 값일 때 성립하는가?","식":["$xy=|xy|\\Longleftrightarrow xy\\ge0$","$P\\subset Q,\\ Q\\not\\subset P$"],"설명":"$x>0$, $y>0$이면 $xy>0$이므로 $P\\subset Q$이다. 반대로 $x=y=0$이면 $xy=|xy|$이지만 $x>0$, $y>0$이 아니므로 $Q\\not\\subset P$이다. 따라서 $p$는 $q$이기 위한 충분조건이지만 필요조건은 아니다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p063-5":{"길":"충분·필요 조건을 화살표로 옮겨 이어 본다","단계":[{"제목":"세 조건을 화살표로 옮기기","힌트":"'A는 B이기 위한 필요조건'은 어느 방향의 화살표인가?","식":["(가) $p\\Rightarrow r$","(나) $r\\Rightarrow q$","(다) $q\\Rightarrow p$"],"설명":"'A는 B이기 위한 충분조건'은 $A\\Rightarrow B$이고, '필요조건'은 $B\\Rightarrow A$이다. (나)는 $q$가 $r$이기 위한 필요조건이므로 $r\\Rightarrow q$이고, (다)는 $p$가 $q$이기 위한 필요조건이므로 $q\\Rightarrow p$이다.","확인":null,"스킬":"C4"},{"제목":"r와 q 사이의 방향 확인","힌트":"(다)와 (가)를 이으면 $q$에서 $r$로 가는 화살표가 생기는가?","식":["$q\\Rightarrow p\\Rightarrow r$","$r\\Leftrightarrow q$"],"설명":"(다)와 (가)를 이으면 $q\\Rightarrow p\\Rightarrow r$이므로 $q\\Rightarrow r$이다. (나)의 $r\\Rightarrow q$와 합치면 $r\\Leftrightarrow q$이므로 $r$는 $q$이기 위한 필요충분조건이다.","확인":null,"스킬":"C4","고비":true}]},"tb-비상공수2-p063-6":{"길":"필요조건이면 Q⊂P — 수직선에 그려 끝점을 비교한다","단계":[{"제목":"q의 진리집합 구하기","힌트":"$x^{2}+5x+6$을 인수분해하면 어떻게 되는가?","식":["$(x+2)(x+3)<0$","$-3<x<-2$"],"설명":"$x^{2}+5x+6=(x+2)(x+3)$이고 곱이 음수이려면 두 인수의 부호가 달라야 하므로 $-3<x<-2$이다. 이것이 $Q$이다.","확인":null,"스킬":"A6"},{"제목":"필요조건을 포함 관계로 바꾸기","힌트":"$p$가 $q$이기 위한 필요조건이면 $P$와 $Q$ 중 어느 쪽이 큰가?","식":["$q\\Rightarrow p$","$Q\\subset P$"],"설명":"$p$가 $q$이기 위한 필요조건이면 $q\\Rightarrow p$이므로 $Q\\subset P$이다. 수직선에 $Q$와 $P=\\{x\\mid-a<x<a\\}$를 그려 끝점을 비교한다.","확인":null,"스킬":"C4"},{"제목":"끝점 비교로 a의 범위 구하기","힌트":"$P$의 왼쪽 끝 $-a$는 $Q$의 왼쪽 끝보다 어느 쪽에 있어야 하는가?","식":["$-a\\le-3$","$a\\ge3$"],"설명":"$Q$가 $P$에 들어가려면 $-a\\le-3$이고 $a\\ge-2$이어야 한다. $a\\ge3$이면 두 조건이 모두 성립하므로 양수 $a$의 최솟값은 3이다.","확인":"3","스킬":"C4","고비":true}]},"tb-비상공수2-p064-4":{"길":"절대부등식은 모든 실수에서 성립 — 반례 하나로 걸러낸다","단계":[{"제목":"항상 성립하는 보기 확인","힌트":"ㄱ에서 좌변에서 우변을 빼면 어떤 식의 제곱이 되는가?","식":["$(a+b)^{2}-4ab=(a-b)^{2}\\ge0$","$-4<0$","$(x-4)^{2}+3\\ge3>0$"],"설명":"ㄱ은 차가 $(a-b)^{2}\\ge0$이므로 항상 성립한다. ㄷ은 양변의 $x^{2}$을 지우면 $-4<0$이므로 항상 성립하고, ㅁ은 $(x-4)^{2}\\ge0$이므로 $(x-4)^{2}+3>0$이 항상 성립한다.","확인":null,"스킬":"C1","고비":true},{"제목":"반례로 ㄴ, ㄹ 거르기","힌트":"ㄴ과 ㄹ이 성립하지 않는 실수 값이 있는가?","식":["ㄴ $a=b=1$: $2>2$","ㄹ $x=-2$: $-2\\ge0$"],"설명":"ㄴ은 $a=b=1$이면 $|a|+|b|=2$, $|a+b|=2$이어서 $2>2$가 거짓이다. ㄹ은 $x=-2$이면 $3x+4=-2$이어서 $-2\\ge0$이 거짓이다. 반례가 있으므로 ㄴ, ㄹ은 절대부등식이 아니고, 답은 ㄱ, ㄷ, ㅁ이다.","확인":null,"스킬":"C3"}]},"tb-비상공수2-p064-6":{"길":"곱이 일정한 두 양수의 합은 산술·기하 평균으로 바로 잡는다","단계":[{"제목":"산술·기하 평균 적용하기","힌트":"두 양수의 합과 곱 사이에는 어떤 부등식이 성립하는가?","식":["$x>0,\\ \\frac{4}{x}>0$","$x+\\frac{4}{x}\\ge2\\sqrt{x\\times\\frac{4}{x}}=2\\sqrt{4}$"],"설명":"$x>0$이면 $\\frac{4}{x}$도 양수이므로 산술·기하 평균을 쓸 수 있다. 곱 $x\\times\\frac{4}{x}$가 $x$에 관계없이 일정하므로 우변도 상수가 된다.","확인":null,"스킬":"A7"},{"제목":"등호 성립 확인과 최솟값","힌트":"$x=\\frac{4}{x}$를 만족하는 양수 $x$가 있는가?","식":["$x=\\frac{4}{x}$, $x=2$","$2\\sqrt{4}=4$"],"설명":"등호는 $x=\\frac{4}{x}$일 때 성립하고, 양수 해 $x=2$가 있으므로 우변의 값에 실제로 도달한다. 따라서 최솟값은 $2\\sqrt{4}$이다.","확인":"4","스킬":"A7","고비":true}]},"tb-비상공수2-p065-2-1":{"길":"정의역의 원소를 하나씩 넣어 나온 함숫값만 모은다","단계":[{"제목":"정의역 원소를 대입하기","힌트":"$x=1,\\ 2,\\ 3$을 $f(x)=4x+3$에 넣으면 각각 얼마인가?","식":["$f(1)=7$","$f(2)=11$","$f(3)=15$"],"설명":"치역은 정의역의 원소를 대입해 실제로 나온 함숫값의 집합이다. 정의역의 원소가 세 개이므로 세 번만 계산하면 된다.","확인":null,"스킬":"T3","고비":true},{"제목":"함숫값을 모아 치역 쓰기","힌트":"얻은 세 값을 중복 없이 집합으로 쓰면 어떻게 되는가?","식":["$\\{7,\\ 11,\\ 15\\}$"],"설명":"세 함숫값이 모두 다르므로 치역은 이 세 값을 원소로 하는 집합이다.","확인":null,"스킬":"T3"}]},"tb-비상공수2-p065-2-2":{"길":"치역은 공역 전체가 아니라 실제로 나온 함숫값만 모은다","단계":[{"제목":"정의역 원소를 대입하기","힌트":"$x=1,\\ 2,\\ 3$을 $g(x)=x^{2}+1$에 넣으면 각각 얼마인가?","식":["$g(1)=2$","$g(2)=5$","$g(3)=10$"],"설명":"정의역의 세 원소를 차례로 대입해 함숫값을 구한다. 제곱을 먼저 계산한 뒤 1을 더한다.","확인":null,"스킬":"T3","고비":true},{"제목":"함숫값을 모아 치역 쓰기","힌트":"얻은 세 값을 중복 없이 집합으로 쓰면 어떻게 되는가?","식":["$\\{2,\\ 5,\\ 10\\}$"],"설명":"세 함숫값이 모두 다르므로 치역은 이 세 값을 원소로 하는 집합이다.","확인":null,"스킬":"T3"}]},"tb-비상공수2-p065-2-3":{"길":"괄호 안을 먼저 더하고 제곱해 함숫값을 모은다","단계":[{"제목":"정의역 원소를 대입하기","힌트":"$x=1,\\ 2,\\ 3$을 $h(x)=(x+1)^{2}$에 넣으면 각각 얼마인가?","식":["$h(1)=4$","$h(2)=9$","$h(3)=16$"],"설명":"괄호 안의 $x+1$을 먼저 계산한 뒤 제곱한다. 예를 들어 $h(1)=(1+1)^{2}$이다.","확인":null,"스킬":"T3","고비":true},{"제목":"함숫값을 모아 치역 쓰기","힌트":"얻은 세 값을 중복 없이 집합으로 쓰면 어떻게 되는가?","식":["$\\{4,\\ 9,\\ 16\\}$"],"설명":"세 함숫값이 모두 다르므로 치역은 이 세 값을 원소로 하는 집합이다.","확인":null,"스킬":"T3"}]},"tb-비상공수2-p065-3":{"길":"정의역의 두 원소에서 두 함수의 함숫값이 같다고 놓는다","단계":[{"제목":"두 원소에서 함숫값 같게 놓기","힌트":"$x=-1$과 $x=1$에서 $f$와 $g$의 값이 같다는 식을 어떻게 쓰는가?","식":["$-a+b=g(-1)=5$","$a+b=g(1)=-1$"],"설명":"두 함수가 서로 같으려면 정의역이 같고 정의역의 모든 원소에서 함숫값이 같아야 한다. 정의역이 $\\{-1,\\ 1\\}$이므로 $f(-1)=g(-1)$, $f(1)=g(1)$ 두 식을 세운다.","확인":null,"스킬":"T3"},{"제목":"연립해서 함수 식 완성","힌트":"두 식을 더하거나 빼면 $a$, $b$는 각각 얼마인가?","식":["$a=-3,\\ b=2$","$f(x)=-3x+2$"],"설명":"두 식을 더하면 $2b=4$이므로 $b=2$이고, 이를 $a+b=-1$에 넣으면 $a=-3$이다. 따라서 $f(x)=-3x+2$이다.","확인":null,"스킬":"A10","고비":true}]},"tb-비상공수2-p065-6":{"길":"같은 함숫값이 겹치는 함수를 먼저 걸러낸다","단계":[{"제목":"(1), (3)에서 겹치는 함숫값","힌트":"(1), (3)에서 서로 다른 $x$가 같은 $y$를 갖는 예가 있는가?","식":["(1) $f(1)=f(-1)=1$","(3) $f(3)=f(-18)=6$"],"설명":"서로 다른 $x$에 같은 $y$가 대응하면 일대일함수가 아니다. (1)은 $x=1$, $x=-1$에서 함숫값이 같다. (3)은 $x\\ge0$에서 $2x=6$이면 $x=3$이고, $x<0$에서 $-\\frac{1}{3}x=6$이면 $x=-18$이므로 같은 값이 두 번 나온다.","확인":null,"스킬":"T3"},{"제목":"(2)가 일대일대응인 이유","힌트":"(2)의 그래프는 수평선과 몇 번 만나는가?","식":["$y=-x+3$의 기울기는 $-1$"],"설명":"$y=-x+3$은 기울기가 0이 아닌 직선이므로 어떤 수평선과도 한 점에서만 만난다. 서로 다른 $x$는 서로 다른 $y$를 갖고 모든 실수 $y$가 나오므로 일대일대응이다.","확인":null,"스킬":"T3","고비":true}]},"tb-비상공수2-p066-2":{"길":"양쪽 합성함수를 식으로 쓰고 상수항을 비교한다","단계":[{"제목":"두 합성함수를 식으로 쓰기","힌트":"$f\\circ g$와 $g\\circ f$에서 각각 어느 함수를 먼저 적용하는가?","식":["$(f\\circ g)(x)=-(ax+1)-2=-ax-3$","$(g\\circ f)(x)=a(-x-2)+1=-ax-2a+1$"],"설명":"$(f\\circ g)(x)=f(g(x))$이므로 $g(x)$를 $f$의 $x$ 자리에 넣는다. $(g\\circ f)(x)=g(f(x))$이므로 $f(x)$를 $g$의 $x$ 자리에 넣는다.","확인":null,"스킬":"T6","고비":true},{"제목":"상수항 비교하기","힌트":"두 식이 모든 $x$에서 같으려면 상수항은 어떻게 되어야 하는가?","식":["$-3=-2a+1$","$a=2$"],"설명":"$x$의 계수는 두 식 모두 $-a$로 같다. 모든 $x$에서 두 식이 같으려면 상수항이 같아야 하므로 $-3=-2a+1$이다.","확인":"2","스킬":"A3"}]},"tb-비상공수2-p066-3":{"길":"안쪽 함수의 치역이 바깥 함수의 정의역 안에 들어가는지 본다","단계":[{"제목":"세 함수의 치역 구하기","힌트":"정의역의 양 끝값을 넣으면 $f$, $g$, $h$의 값의 범위는 각각 어떻게 되는가?","식":["$f$의 치역 $2\\le y\\le7$","$g$의 치역 $0\\le y\\le4$","$h$의 치역 $0\\le y\\le6$"],"설명":"$f$는 증가하므로 $x=0$, $x=5$에서 2와 7이 양 끝이다. $g=x^{2}$은 $x=0$에서 0, $x=\\pm2$에서 4이고, $h$는 감소하므로 $x=3$, $x=-3$에서 0과 6이 양 끝이다.","확인":null,"스킬":"T3"},{"제목":"치역과 정의역의 포함 관계 확인","힌트":"$A\\circ B$가 정의되려면 $B$의 치역이 $A$의 정의역에 들어 있어야 하는가?","식":["ㄱ $g\\circ f$: $2\\le y\\le7$의 일부가 $-2\\le x\\le2$ 밖","ㄴ $f\\circ h$: $0\\le y\\le6$의 일부가 $0\\le x\\le5$ 밖","ㄷ $f\\circ g$: $0\\le y\\le4$가 $0\\le x\\le5$에 모두 포함","ㄹ $h\\circ g$: $0\\le y\\le4$의 일부가 $-3\\le x\\le3$ 밖"],"설명":"$A\\circ B$는 $B$를 먼저 적용하므로 $B$의 치역이 $A$의 정의역에 모두 들어가야 정의된다. 이 조건을 만족하는 것은 ㄷ뿐이고, 나머지는 치역의 일부가 정의역을 벗어난다.","확인":null,"스킬":"T6","고비":true}]},"tb-비상공수2-p066-4":{"길":"결합법칙으로 h∘g를 한 덩어리로 묶어 주어진 식을 쓴다","단계":[{"제목":"결합법칙으로 묶는 방법 바꾸기","힌트":"$h\\circ(g\\circ f)$를 $(h\\circ g)\\circ f$로 묶어도 값이 같은가?","식":["$(h\\circ(g\\circ f))(3)=((h\\circ g)\\circ f)(3)=(h\\circ g)(f(3))$"],"설명":"함수의 합성은 결합법칙이 성립하므로 묶는 순서를 바꿔도 값이 같다. $h\\circ g$를 한 덩어리로 보면 $g$, $h$를 따로 구하지 않아도 주어진 $(x-2)^{2}$을 바로 쓸 수 있다.","확인":null,"스킬":"T6","고비":true},{"제목":"안쪽 함수의 값 구하기","힌트":"$f(3)$은 얼마인가?","식":["$f(3)=3+2=5$"],"설명":"$(h\\circ g)(f(3))$에서 가장 안쪽의 $f(3)$을 먼저 계산한다.","확인":"5","스킬":"T6"},{"제목":"묶은 합성함수에 대입하기","힌트":"$(h\\circ g)(x)=(x-2)^{2}$의 $x$에 앞에서 구한 값을 넣으면 얼마인가?","식":["$(h\\circ g)(5)=(5-2)^{2}=9$"],"설명":"$(h\\circ g)(x)=(x-2)^{2}$이므로 $x=5$를 넣으면 $3^{2}$이다.","확인":"9","스킬":"T6"}]},"tb-비상공수2-p066-5":{"길":"g(5)가 필요하니 괄호 안이 5가 되는 x를 찾아 넣는다","단계":[{"제목":"g(5)가 되는 x 찾기","힌트":"$g(2x-1)$의 괄호 안이 5가 되려면 $x$는 얼마인가?","식":["$2x-1=5$","$x=3$"],"설명":"$g(5)$를 직접 알 수 없으므로 $g(2x-1)=-6x+5$에서 괄호 안이 5가 되는 $x$를 찾는다. $2x-1=5$를 풀면 $x=3$이다.","확인":"3","스킬":"T6","고비":true},{"제목":"g(5)의 값 구하기","힌트":"$x=3$을 $-6x+5$에 넣으면 얼마인가?","식":["$g(5)=-6\\times3+5=-13$"],"설명":"$g(2x-1)=-6x+5$에 $x=3$을 넣으면 $g(5)$의 값이 나온다.","확인":"-13","스킬":"T6"},{"제목":"f에 대입하기","힌트":"$f(x)=2x-3$에 앞에서 구한 값을 넣으면 얼마인가?","식":["$(f\\circ g)(5)=f(-13)=2\\times(-13)-3=-29$"],"설명":"$(f\\circ g)(5)=f(g(5))$이므로 $g(5)$의 값을 $f$의 $x$ 자리에 넣는다.","확인":"-29","스킬":"T6"}]},"tb-비상공수2-p066-6":{"길":"g에 h(x)를 통째로 넣고 h(x)에 대한 식으로 푼다","단계":[{"제목":"g(h(x))를 식으로 쓰기","힌트":"$g(x)=-x+2$의 $x$ 자리에 $h(x)$를 넣으면 어떤 식이 되는가?","식":["$(g\\circ h)(x)=-h(x)+2$","$-h(x)+2=3x-1$"],"설명":"$(g\\circ h)(x)=g(h(x))$이므로 $g$의 $x$ 자리에 $h(x)$를 통째로 넣는다. $g\\circ h=f$이므로 이 식이 $f(x)=3x-1$과 같다.","확인":null,"스킬":"T6","고비":true},{"제목":"h(x)에 대해 풀기","힌트":"$-h(x)+2=3x-1$에서 $h(x)$를 구하면 어떻게 되는가?","식":["$-h(x)=3x-3$","$h(x)=-3x+3$"],"설명":"2를 우변으로 넘기면 $-h(x)=3x-3$이고, 양변에 $-1$을 곱하면 $h(x)=-3x+3$이다. 일차함수이므로 조건에 맞는다.","확인":null,"스킬":"T6"}]},"tb-비상공수2-p067-1-1":{"길":"f의 역함수의 값은 화살표를 거꾸로 읽는다","단계":[{"제목":"역함수의 값을 정의로 바꾸기","힌트":"$f^{-1}(6)=k$이면 $f(k)$는 얼마인가?","식":["$f^{-1}(6)=k\\Longleftrightarrow f(k)=6$"],"설명":"역함수는 $f$의 대응을 거꾸로 한 함수이므로 $f^{-1}(6)=k$이면 $f(k)=6$이다. 6으로 들어오는 화살표의 출발점을 찾으면 된다.","확인":null,"스킬":"T1","고비":true},{"제목":"그림에서 6이 나오는 원소 찾기","힌트":"그림에서 오른쪽 6에 닿는 화살표는 왼쪽의 어느 원소에서 출발하는가?","식":["$f(4)=6$","$f^{-1}(6)=4$"],"설명":"그림에서 왼쪽 4에서 출발한 화살표가 오른쪽 6에 닿으므로 $f(4)=6$이다. 따라서 $f^{-1}(6)$은 출발점인 4이다.","확인":"4","스킬":"T1"}]},"tb-비상공수2-p067-1-2":{"길":"f로 보낸 값을 f의 역함수로 되돌리면 처음 값이 나온다","단계":[{"제목":"안쪽 함숫값 구하기","힌트":"그림에서 왼쪽 2에서 출발한 화살표는 오른쪽 어느 원소에 닿는가?","식":["$f(2)=4$"],"설명":"$(f^{-1}\\circ f)(2)=f^{-1}(f(2))$이므로 안쪽의 $f(2)$를 먼저 구한다. 그림에서 2에서 출발한 화살표가 4에 닿는다.","확인":"4","스킬":"T1"},{"제목":"역함수로 되돌리기","힌트":"$f^{-1}(4)=k$이면 $f(k)$는 얼마인가?","식":["$f^{-1}(4)=2$"],"설명":"$f^{-1}(4)=k$이면 $f(k)=4$이고, 4에 닿는 화살표의 출발점은 2이다. $f^{-1}\\circ f$는 항등함수이므로 처음 값 2가 그대로 나온다.","확인":"2","스킬":"T1","고비":true}]},"tb-비상공수2-p067-2":{"길":"역함수 조건을 함수 조건으로 바꿔 연립방정식을 세운다","단계":[{"제목":"역함수 조건을 함수 조건으로 바꾸기","힌트":"$f^{-1}(5)=-1$이면 $f(-1)$은 얼마인가?","식":["$f^{-1}(5)=-1\\Longleftrightarrow f(-1)=5$"],"설명":"$f^{-1}(b)=a$이면 $f(a)=b$이다. 따라서 $f^{-1}(5)=-1$은 $f(-1)=5$와 같은 조건이다.","확인":null,"스킬":"T1","고비":true},{"제목":"연립해서 a, b 구하기","힌트":"$f(2)=-4$와 $f(-1)=5$를 $ax+b$에 넣어 두 식을 세우면 $a$, $b$는 각각 얼마인가?","식":["$2a+b=-4$","$-a+b=5$","$a=-3,\\ b=2$"],"설명":"첫째 식에서 둘째 식을 빼면 $3a=-9$이므로 $a=-3$이다. 이를 $-a+b=5$에 넣으면 $b=2$이다.","확인":null,"스킬":"A10"},{"제목":"f(3) 계산하기","힌트":"$f(x)=-3x+2$에 $x=3$을 넣으면 얼마인가?","식":["$f(3)=-3\\times3+2=-7$"],"설명":"구한 $a$, $b$로 $f(x)=-3x+2$이므로 $x=3$을 대입한다.","확인":"-7","스킬":"T1"}]},"tb-비상공수2-p067-3":{"길":"x에 대해 풀고 x, y를 바꾼 뒤 계수를 비교한다","단계":[{"제목":"f의 역함수 식 구하기","힌트":"$y=ax-3$을 $x$에 대해 풀고 $x$와 $y$를 바꾸면 어떤 식이 되는가?","식":["$x=\\frac{1}{a}y+\\frac{3}{a}$","$f^{-1}(x)=\\frac{1}{a}x+\\frac{3}{a}$"],"설명":"$y=ax-3$에서 $ax=y+3$이므로 $x=\\frac{1}{a}y+\\frac{3}{a}$이다. $x$와 $y$를 서로 바꾸면 $f$의 역함수 식을 얻는다.","확인":null,"스킬":"T1","고비":true},{"제목":"계수 비교로 a, b 구하기","힌트":"$\\frac{1}{a}x+\\frac{3}{a}$과 $\\frac{1}{3}x+b$가 같으려면 $x$의 계수와 상수항은 각각 어떻게 되어야 하는가?","식":["$\\frac{1}{a}=\\frac{1}{3}$","$\\frac{3}{a}=b$","$a=3,\\ b=1$"],"설명":"두 일차식이 같으려면 $x$의 계수와 상수항이 각각 같아야 한다. $\\frac{1}{a}=\\frac{1}{3}$에서 $a=3$이고, $b=\\frac{3}{a}$에 넣으면 $b=1$이다.","확인":null,"스킬":"A3"}]},"tb-비상공수2-p067-4-1":{"길":"역함수의 역함수는 원래 함수임을 이용한다","단계":[{"제목":"역함수의 역함수 정리하기","힌트":"$f^{-1}$의 역함수는 어떤 함수인가?","식":["$(f^{-1})^{-1}=f$"],"설명":"$f$와 $f^{-1}$은 서로 역함수 관계이므로 $f^{-1}$의 역함수는 원래의 $f$이다. 따라서 $(f^{-1})^{-1}(3)=f(3)$이다.","확인":null,"스킬":"T1","고비":true},{"제목":"f의 함숫값 구하기","힌트":"$f(x)=2x+3$에 $x=3$을 넣으면 얼마인가?","식":["$f(3)=2\\times3+3=9$"],"설명":"$f(x)=2x+3$의 $x$에 3을 대입한다.","확인":"9","스킬":"T1"}]},"tb-비상공수2-p067-4-2":{"길":"역함수를 구하지 말고 (g∘f)(x)=3인 x를 찾는다","단계":[{"제목":"합성함수 g∘f 구하기","힌트":"$g(x)=4x-1$의 $x$ 자리에 $f(x)$를 넣으면 어떤 식이 되는가?","식":["$(g\\circ f)(x)=4(2x+3)-1=8x+11$"],"설명":"$(g\\circ f)(x)=g(f(x))$이므로 $g$의 $x$ 자리에 $2x+3$을 넣고 전개한다.","확인":null,"스킬":"T6"},{"제목":"역함수의 값을 방정식으로 바꾸기","힌트":"$(g\\circ f)^{-1}(3)=k$이면 $(g\\circ f)(k)$는 얼마인가?","식":["$(g\\circ f)^{-1}(3)=k\\Longleftrightarrow(g\\circ f)(k)=3$","$8k+11=3$"],"설명":"역함수의 값 $k$는 $(g\\circ f)(k)=3$을 만족하는 $k$이다. 역함수 식을 따로 구하지 않고 $8k+11=3$을 푼다.","확인":null,"스킬":"T1","고비":true},{"제목":"방정식 풀기","힌트":"$8k+11=3$에서 $k$는 얼마인가?","식":["$8k=-8$","$k=-1$"],"설명":"11을 우변으로 넘기면 $8k=-8$이므로 $k=-1$이다. 따라서 $(g\\circ f)^{-1}(3)=-1$이다.","확인":"-1","스킬":"T1"}]},"tb-비상공수2-p067-5":{"길":"f⁻¹∘g⁻¹=(g∘f)⁻¹ — 두 항이 같은 값임을 이용한다","단계":[{"제목":"합성함수 g∘f 구하기","힌트":"$g(x)=x+2$의 $x$ 자리에 $f(x)$를 넣으면 어떤 식이 되는가?","식":["$(g\\circ f)(x)=(2x-1)+2=2x+1$"],"설명":"$(g\\circ f)(x)=g(f(x))$이므로 $g$의 $x$ 자리에 $2x-1$을 넣는다.","확인":null,"스킬":"T6"},{"제목":"첫째 항의 값 구하기","힌트":"$(g\\circ f)(k)=2$를 만족하는 $k$는 얼마인가?","식":["$2k+1=2$","$k=\\frac{1}{2}$"],"설명":"$(g\\circ f)^{-1}(2)=k$이면 $(g\\circ f)(k)=2$이다. $2k+1=2$를 풀면 $k=\\frac{1}{2}$이다.","확인":"1/2","스킬":"T1"},{"제목":"둘째 항을 같은 꼴로 바꾸기","힌트":"$f^{-1}\\circ g^{-1}$은 어떤 합성함수의 역함수와 같은가?","식":["$f^{-1}\\circ g^{-1}=(g\\circ f)^{-1}$"],"설명":"합성함수의 역함수는 순서가 뒤집히므로 $(g\\circ f)^{-1}=f^{-1}\\circ g^{-1}$이다. 따라서 둘째 항도 첫째 항과 같은 값이다.","확인":null,"스킬":"T1","고비":true},{"제목":"두 항의 합 구하기","힌트":"같은 값 두 개를 더하면 얼마인가?","식":["$\\frac{1}{2}+\\frac{1}{2}=1$"],"설명":"첫째 항과 둘째 항이 모두 $\\frac{1}{2}$이므로 합은 1이다.","확인":"1","스킬":"T1"}]},"tb-비상공수2-p067-6":{"길":"증가하는 함수와 그 역함수의 교점은 y=x 위에서 찾는다","단계":[{"제목":"교점이 놓이는 직선 찾기","힌트":"함수와 그 역함수의 그래프는 어떤 직선에 대해 대칭인가?","식":["$y=x$"],"설명":"함수와 그 역함수의 그래프는 직선 $y=x$에 대해 대칭이다. 주어진 함수가 증가하는 일차함수이므로 두 그래프의 교점은 $y=x$ 위에 있다.","확인":null,"스킬":"T1","고비":true},{"제목":"y=x와 연립하기","힌트":"$\\frac{1}{2}x+\\frac{3}{4}=x$를 풀면 $x$는 얼마인가?","식":["$\\frac{1}{2}x+\\frac{3}{4}=x$","$x=\\frac{3}{2}$"],"설명":"$y=x$를 주어진 함수에 대입하면 $\\frac{1}{2}x+\\frac{3}{4}=x$이다. 정리하면 $\\frac{1}{2}x=\\frac{3}{4}$이므로 $x=\\frac{3}{2}$이다.","확인":"3/2","스킬":"G1"},{"제목":"교점의 좌표 쓰기","힌트":"교점이 $y=x$ 위에 있으면 $y$좌표는 $x$좌표와 어떤 관계인가?","식":["$\\left(\\frac{3}{2},\\ \\frac{3}{2}\\right)$"],"설명":"교점이 $y=x$ 위에 있으므로 $y$좌표도 $x$좌표와 같다.","확인":null,"스킬":"G1"}]},"tb-비상공수2-p068-1":{"길":"모두 인수분해하고 나눗셈은 뒤집어 곱한 뒤 약분한다","단계":[{"제목":"분자와 분모를 모두 인수분해","힌트":"네 개의 이차식은 각각 어떤 두 일차식의 곱으로 나뉘는가?","식":["$x^{2}-6x=x(x-6)$, $x^{2}+x-2=(x-1)(x+2)$","$x^{2}+5x+6=(x+2)(x+3)$, $x^{2}-3x-18=(x-6)(x+3)$"],"설명":"인수분해를 해야 공통인수를 찾아 약분할 수 있다. $x^{2}+x-2$는 곱이 $-2$, 합이 $1$인 두 수 $2$, $-1$로 나뉘고, $x^{2}-3x-18$은 곱이 $-18$, 합이 $-3$인 두 수 $-6$, $3$으로 나뉜다.","확인":null,"스킬":"A1"},{"제목":"나눗셈을 곱셈으로 바꾸기","힌트":"마지막 분수로 나누는 것은 그 분수의 역수를 곱하는 것과 같은가?","식":["$\\frac{x(x-6)}{(x-1)(x+2)}\\times\\frac{(x+2)(x+3)}{x+1}\\times\\frac{x-1}{(x+3)(x-6)}$"],"설명":"분수로 나누는 것은 역수를 곱하는 것과 같으므로 마지막 분수를 뒤집어 곱한다. 이때 $x-1$이 분자로 올라온다.","확인":null,"스킬":"A1","고비":true},{"제목":"공통인수 약분하기","힌트":"분자와 분모에 함께 있는 인수는 무엇인가?","식":["$\\frac{x}{x+1}$"],"설명":"분자와 분모에 공통으로 있는 $(x-6)$, $(x-1)$, $(x+2)$, $(x+3)$을 모두 약분하면 분자에 $x$, 분모에 $x+1$만 남는다.","확인":null,"스킬":"A1"}]},"tb-비상공수2-p068-2-1":{"길":"x 대신 x-1, y 대신 y-2를 넣고 y에 대해 정리한다","단계":[{"제목":"평행이동한 식에 대입하기","힌트":"$x$축으로 1, $y$축으로 2만큼 옮기면 $x$와 $y$ 자리에 각각 무엇을 넣는가?","식":["$y-2=\\frac{3}{x-1}$"],"설명":"$x$축 방향으로 $m$만큼, $y$축 방향으로 $n$만큼 평행이동하면 $x$ 대신 $x-m$, $y$ 대신 $y-n$을 넣는다. 부호가 반대로 들어간다.","확인":null,"스킬":"G4","고비":true},{"제목":"y에 대해 정리하기","힌트":"$y-2=\\frac{3}{x-1}$에서 2를 우변으로 옮기면 어떤 식이 되는가?","식":["$y=\\frac{3}{x-1}+2$"],"설명":"2를 우변으로 넘기면 $y=\\frac{3}{x-1}+2$이다. 점근선은 $x=1$, $y=2$로 옮겨진다.","확인":null,"스킬":"T4"}]},"tb-비상공수2-p068-2-2":{"길":"x 대신 x-1, y 대신 y-2를 넣고 y에 대해 정리한다","단계":[{"제목":"평행이동한 식에 대입하기","힌트":"$x$축으로 1, $y$축으로 2만큼 옮기면 $x$와 $y$ 자리에 각각 무엇을 넣는가?","식":["$y-2=-\\frac{1}{x-1}$"],"설명":"$x$축 방향으로 $m$만큼, $y$축 방향으로 $n$만큼 평행이동하면 $x$ 대신 $x-m$, $y$ 대신 $y-n$을 넣는다. 부호가 반대로 들어간다.","확인":null,"스킬":"G4","고비":true},{"제목":"y에 대해 정리하기","힌트":"$y-2=-\\frac{1}{x-1}$에서 2를 우변으로 옮기면 어떤 식이 되는가?","식":["$y=-\\frac{1}{x-1}+2$"],"설명":"2를 우변으로 넘기면 $y=-\\frac{1}{x-1}+2$이다. 점근선은 $x=1$, $y=2$로 옮겨진다.","확인":null,"스킬":"T4"}]},"tb-비상공수2-p068-3":{"길":"점근선을 먼저 긋고 k의 부호로 곡선이 놓일 칸을 정한다","단계":[{"제목":"점근선과 곡선이 놓일 칸 정하기","힌트":"$y=\\frac{k}{x-p}+q$의 점근선은 무엇이며, $k<0$이면 곡선은 어느 두 칸에 놓이는가?","식":["$x=3,\\ y=5$","$k=-3<0$"],"설명":"점근선은 $x=3$, $y=5$이다. $k=-3<0$이므로 곡선은 점근선이 나누는 네 칸 중 왼쪽 위와 오른쪽 아래에 놓인다.","확인":null,"스킬":"T4"},{"제목":"왼쪽 위 가지의 좌표 범위","힌트":"왼쪽 위 가지에서 $y$좌표는 어떤 범위에 있는가?","식":["$x<3,\\ y>5$"],"설명":"왼쪽 위 가지는 항상 $y>5$이므로 $y$좌표가 양수이다. 제3사분면은 $y<0$이므로 이 가지는 제3사분면을 지나지 않는다.","확인":null,"스킬":"T4","고비":true},{"제목":"오른쪽 아래 가지의 좌표 범위","힌트":"오른쪽 아래 가지에서 $x$좌표는 어떤 범위에 있는가?","식":["$x>3,\\ y<5$"],"설명":"오른쪽 아래 가지는 항상 $x>3$이므로 $x$좌표가 양수이다. 제3사분면은 $x<0$이므로 이 가지도 제3사분면을 지나지 않는다. 따라서 그래프가 지나지 않는 사분면은 제3사분면이다.","확인":null,"스킬":"T4"}]},"tb-비상공수2-p068-4":{"길":"정의역에서 빠진 값은 x=a, 치역에서 빠진 값은 y=b","단계":[{"제목":"점근선을 읽을 수 있는 꼴로 바꾸기","힌트":"분자 $bx+3$을 $b(x-a)$를 포함하는 꼴로 쓰면 식이 어떻게 되는가?","식":["$y=\\frac{b(x-a)+ab+3}{x-a}=\\frac{ab+3}{x-a}+b$"],"설명":"분자를 $b(x-a)+ab+3$으로 고쳐 분모로 나누면 $\\frac{k}{x-p}+q$ 꼴이 된다. 이 꼴에서 점근선은 $x=a$, $y=b$이다.","확인":null,"스킬":"T4","고비":true},{"제목":"정의역·치역과 점근선 비교","힌트":"정의역에서 빠진 값과 치역에서 빠진 값은 각각 어느 점근선과 같은가?","식":["$a=2,\\ b=-3$"],"설명":"정의역에서 빠진 값이 $x=a$이므로 $a=2$이고, 치역에서 빠진 값이 $y=b$이므로 $b=-3$이다. 이때 $ab+3=-3\\ne0$이므로 실제로 유리함수가 된다.","확인":null,"스킬":"T4"}]},"tb-비상공수2-p068-5":{"길":"분자를 분모로 나눠 k/(x-p)+q 꼴로 바꿔 점근선을 읽는다","단계":[{"제목":"k/(x-p)+q 꼴로 바꾸기","힌트":"분자 $2x-1$을 $2(x-1)$을 포함하는 꼴로 쓰면 식이 어떻게 되는가?","식":["$y=\\frac{2(x-1)+1}{x-1}=\\frac{1}{x-1}+2$"],"설명":"$2x-1=2(x-1)+1$로 고쳐 분모로 나누면 상수 부분이 분리된다. 이 꼴에서 점근선을 바로 읽을 수 있다.","확인":null,"스킬":"T4","고비":true},{"제목":"점근선 읽기","힌트":"$y=\\frac{1}{x-1}+2$의 점근선은 어느 두 직선인가?","식":["$x=1,\\ y=2$"],"설명":"$y=\\frac{k}{x-p}+q$의 점근선은 $x=p$, $y=q$이다. 따라서 $a$, $b$의 값이 정해진다.","확인":null,"스킬":"T4"},{"제목":"ab의 값 계산","힌트":"구한 $a$, $b$를 곱하면 얼마인가?","식":["$ab=1\\times2=2$"],"설명":"점근선에서 읽은 $a$와 $b$를 곱한다.","확인":"2","스킬":"T4"}]},"tb-비상공수2-p069-1":{"길":"대입 전에 통분해 식을 간단히 하면 분모의 √x가 사라진다","단계":[{"제목":"대입 전에 통분하기","힌트":"두 분수의 공통분모는 무엇이며, 분자는 어떻게 전개되는가?","식":["$\\frac{(\\sqrt{x}-1)^{2}+(\\sqrt{x}+1)^{2}}{(\\sqrt{x}+1)(\\sqrt{x}-1)}$","$=\\frac{2x+2}{x-1}$"],"설명":"공통분모는 $(\\sqrt{x}+1)(\\sqrt{x}-1)=x-1$이다. 분자는 $(x-2\\sqrt{x}+1)+(x+2\\sqrt{x}+1)=2x+2$이므로 $\\sqrt{x}$가 모두 사라진다.","확인":null,"스킬":"A1","고비":true},{"제목":"x=√2 대입하기","힌트":"$\\frac{2(x+1)}{x-1}$의 $x$에 $\\sqrt{2}$를 넣으면 어떻게 되는가?","식":["$\\frac{2(\\sqrt{2}+1)}{\\sqrt{2}-1}$"],"설명":"통분한 식 $\\frac{2(x+1)}{x-1}$에 $x=\\sqrt{2}$를 대입한다.","확인":null,"스킬":"A1"},{"제목":"분모 유리화하기","힌트":"분모 $\\sqrt{2}-1$에 어떤 수를 곱하면 근호가 사라지는가?","식":["$2(\\sqrt{2}+1)^{2}=2(3+2\\sqrt{2})=6+4\\sqrt{2}$"],"설명":"분자와 분모에 $\\sqrt{2}+1$을 곱하면 분모가 $(\\sqrt{2}-1)(\\sqrt{2}+1)=1$이 된다. 분자는 $2(\\sqrt{2}+1)^{2}$이므로 전개해 정리한다.","확인":null,"스킬":"A5"}]},"tb-비상공수2-p069-2":{"길":"근호 안 ≥0으로 정의역, 근호 앞 부호로 치역의 방향을 정한다","단계":[{"제목":"근호 안이 0 이상일 조건","힌트":"$20-5x\\ge0$을 풀면 $x$의 범위는 어떻게 되는가?","식":["$20-5x\\ge0$","$x\\le4$"],"설명":"근호 안의 값이 0 이상이어야 하므로 $20-5x\\ge0$이다. 정의역이 $x\\le b$로 주어졌으므로 $b$는 이 범위의 끝값이다.","확인":null,"스킬":"T3"},{"제목":"근호 앞 부호로 치역 정하기","힌트":"$-\\sqrt{20-5x}$의 값은 0 이하인가, 0 이상인가?","식":["$-\\sqrt{20-5x}\\le0$","$y\\le a$","$a=3,\\ b=4$"],"설명":"근호 앞이 음수이므로 $-\\sqrt{20-5x}\\le0$이고, 따라서 $y\\le a$이다. 치역이 $y\\le3$이므로 $a=3$이고, 앞에서 구한 끝값으로 $b=4$이다.","확인":null,"스킬":"T3","고비":true}]},"tb-비상공수2-p069-4":{"길":"근호 안을 2(x-□) 꼴로 묶어야 x축 이동량이 보인다","단계":[{"제목":"근호 안을 2(x-□) 꼴로 묶기","힌트":"$2x-1$에서 $x$ 앞의 계수 2를 묶어 내면 어떻게 되는가?","식":["$y=\\sqrt{2\\left(x-\\frac{1}{2}\\right)}+3$"],"설명":"$y=\\sqrt{2x}$를 평행이동하면 $x$ 자리에 $x-a$가 들어가므로 근호 안을 $2(x-a)$ 꼴로 만들어야 한다. $2x-1=2\\left(x-\\frac{1}{2}\\right)$이다.","확인":"1/2","스킬":"G4","고비":true},{"제목":"이동량 읽기","힌트":"$y=\\sqrt{2(x-a)}+b$와 비교하면 $a$, $b$는 각각 얼마인가?","식":["$a=\\frac{1}{2},\\ b=3$"],"설명":"$x-a$와 $x-\\frac{1}{2}$를 비교하면 $a=\\frac{1}{2}$이고, 뒤의 상수항 $+3$이 $y$축 방향 이동량 $b$이다.","확인":null,"스킬":"G4"}]},"tb-비상공수2-p069-6":{"길":"근호 앞이 마이너스면 감소함수 — 양 끝값이 곧 최대·최소","단계":[{"제목":"증가·감소 판단하기","힌트":"$x$가 커질수록 $\\sqrt{2x+4}$와 $-\\sqrt{2x+4}+1$은 각각 어떻게 변하는가?","식":["$x$가 커지면 $y$는 작아진다"],"설명":"근호 안의 $2x+4$는 $x$가 커질수록 커지지만 근호 앞이 음수이므로 $y$는 작아진다. 따라서 $x=0$에서 최대, $x=6$에서 최소이다.","확인":null,"스킬":"T3","고비":true},{"제목":"x=0에서의 함숫값","힌트":"$x=0$을 대입하면 $y$는 얼마인가?","식":["$y=-\\sqrt{4}+1=-1$"],"설명":"$x=0$일 때 근호 안은 4이므로 $y=-2+1$이다. 이 값이 최댓값이다.","확인":"-1","스킬":"T3"},{"제목":"x=6에서의 함숫값","힌트":"$x=6$을 대입하면 $y$는 얼마인가?","식":["$y=-\\sqrt{16}+1=-3$"],"설명":"$x=6$일 때 근호 안은 16이므로 $y=-4+1$이다. 이 값이 최솟값이다.","확인":null,"스킬":"T3"}]}});
